[workspace]
resolver = "2"
members = [
    "crates/ferret-core",
    "crates/ferret-store",
    "crates/ferret-ingest",
    "crates/ferret-teachers",
    "crates/ferret-index",
    "crates/ferret-infer",
    "crates/ferret-route",
    "crates/ferret-padagonia",
    "crates/ferret-daemon",
    "crates/ferret-cli",
]

[workspace.package]
version = "0.1.0"
edition = "2021"
license = "MIT"
repository = "https://github.com/elci-group/ferret"

[workspace.dependencies]
ferret-core = { path = "crates/ferret-core" }
ferret-store = { path = "crates/ferret-store" }
ferret-ingest = { path = "crates/ferret-ingest" }
ferret-teachers = { path = "crates/ferret-teachers" }
ferret-index = { path = "crates/ferret-index" }
ferret-infer = { path = "crates/ferret-infer" }
ferret-route = { path = "crates/ferret-route" }
ferret-padagonia = { path = "crates/ferret-padagonia" }
form3 = { path = "../3form" }

anyhow = "1.0"
async-trait = "0.1"
axum = "0.8"
chrono = { version = "0.4", features = ["serde"] }
clap = { version = "4.5", features = ["derive"] }
git2 = "0.20"
serde = { version = "1.0", features = ["derive"] }
serde_json = "1.0"
sha2 = "0.10"
similar = "2.7"
sqlx = { version = "0.8", features = ["runtime-tokio", "sqlite", "chrono", "json"] }
tokio = { version = "1.43", features = ["full"] }
tracing = "0.1"
tracing-subscriber = { version = "0.3", features = ["env-filter"] }
uuid = { version = "1.11", features = ["v4", "serde"] }

use anyhow::{bail, Context, Result};
use serde::Serialize;
use std::collections::{BTreeMap, BTreeSet, HashSet};
use std::fmt;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

pub const DEFAULT_EXCLUSIONS: &[&str] = &[
    ".git",
    "target",
    "node_modules",
    "vendor",
    ".cache",
    "tmp",
    "temp",
    "build",
    "dist",
];

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum ProjectKind {
    Rust,
    Node,
    Python,
    Go,
    Php,
    Ruby,
    Elixir,
    Java,
    DotNet,
}

impl ProjectKind {
    pub fn parse(value: &str) -> Option<Self> {
        match value.to_ascii_lowercase().as_str() {
            "rust" => Some(Self::Rust),
            "node" | "javascript" | "typescript" => Some(Self::Node),
            "python" => Some(Self::Python),
            "go" => Some(Self::Go),
            "php" => Some(Self::Php),
            "ruby" => Some(Self::Ruby),
            "elixir" => Some(Self::Elixir),
            "java" => Some(Self::Java),
            "dotnet" | ".net" | "csharp" => Some(Self::DotNet),
            _ => None,
        }
    }
}

impl fmt::Display for ProjectKind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{self:?}")
    }
}

#[derive(Debug, Clone, Serialize)]
pub struct ProjectIdentity {
    pub canonical_path: PathBuf,
    pub project_kind: ProjectKind,
    pub project_name: String,
    pub project_manifest: PathBuf,
    pub repository_root: Option<PathBuf>,
    pub git: Option<GitMetadata>,
}

#[derive(Debug, Clone, Serialize)]
pub struct GitMetadata {
    pub branch: Option<String>,
    pub dirty: bool,
    pub remote: Option<String>,
    pub last_commit: Option<String>,
    pub ahead: Option<usize>,
    pub behind: Option<usize>,
}

#[derive(Debug, Clone)]
pub struct DiscoveryOptions {
    pub max_depth: usize,
    pub include: Vec<String>,
    pub exclude: Vec<String>,
    pub project_kind: Option<ProjectKind>,
    pub follow_symlinks: bool,
    pub git: bool,
}

impl Default for DiscoveryOptions {
    fn default() -> Self {
        Self {
            max_depth: 12,
            include: Vec::new(),
            exclude: DEFAULT_EXCLUSIONS.iter().map(|s| (*s).to_owned()).collect(),
            project_kind: None,
            follow_symlinks: false,
            git: true,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct FindingSummary {
    pub category: String,
    pub severity: String,
    pub message: String,
    pub rule_id: Option<String>,
    pub file: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct ProjectAnalysis {
    pub files_scanned: usize,
    pub findings: Vec<FindingSummary>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum ProjectStatus {
    Passed,
    Warning,
    Error,
}

#[derive(Debug, Clone, Serialize)]
pub struct ProjectResult {
    #[serde(flatten)]
    pub project: ProjectIdentity,
    pub status: ProjectStatus,
    pub analysis: Option<ProjectAnalysis>,
    pub error: Option<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct BusinessFinding {
    pub severity: String,
    pub code: String,
    pub message: String,
    pub projects: Vec<PathBuf>,
}

#[derive(Debug, Clone, Serialize)]
pub struct BusinessSummary {
    pub discovered: usize,
    pub scanned: usize,
    pub successful: usize,
    pub warnings: usize,
    pub errors: usize,
}

#[derive(Debug, Clone, Serialize)]
pub struct BusinessReport {
    pub schema: &'static str,
    pub root: PathBuf,
    pub projects: Vec<ProjectResult>,
    pub business_findings: Vec<BusinessFinding>,
    pub summary: BusinessSummary,
}

impl BusinessReport {
    pub fn exit_code(&self) -> u8 {
        if self.summary.errors > 0 {
            2
        } else if self.summary.warnings > 0 || !self.business_findings.is_empty() {
            1
        } else {
            0
        }
    }
}

pub fn project_at(target: &Path, git: bool) -> Result<ProjectIdentity> {
    let canonical = target
        .canonicalize()
        .with_context(|| format!("target does not exist: {}", target.display()))?;
    if !canonical.is_dir() {
        bail!("target is not a directory: {}", canonical.display());
    }
    let Some((kind, manifest)) = marker_at(&canonical) else {
        bail!(
            "target_not_project\ntarget: {}\nreason: no recognised project boundary\nhint: use `ferret business` for multi-project discovery",
            canonical.display()
        );
    };
    Ok(identity(canonical, kind, manifest, git))
}

pub fn discover(root: &Path, options: &DiscoveryOptions) -> Result<Vec<ProjectIdentity>> {
    let root = root
        .canonicalize()
        .with_context(|| format!("discovery root does not exist: {}", root.display()))?;
    if !root.is_dir() {
        bail!("discovery root is not a directory: {}", root.display());
    }

    let mut candidates = Vec::new();
    let mut stack = vec![(root.clone(), 0usize)];
    let mut visited = HashSet::new();
    visited.insert(root.clone());

    while let Some((directory, depth)) = stack.pop() {
        if let Some((kind, manifest)) = marker_at(&directory) {
            let relative = directory.strip_prefix(&root).unwrap_or(&directory);
            if options.project_kind.is_none_or(|wanted| wanted == kind)
                && matches_filters(relative, &options.include)
            {
                candidates.push((directory.clone(), kind, manifest));
            }
        }

        if depth >= options.max_depth {
            continue;
        }
        let entries = match std::fs::read_dir(&directory) {
            Ok(entries) => entries,
            Err(_) => continue,
        };
        let mut children = entries.flatten().collect::<Vec<_>>();
        children.sort_by_key(|entry| entry.file_name());
        for entry in children.into_iter().rev() {
            let name = entry.file_name().to_string_lossy().into_owned();
            let path = entry.path();
            let relative = path.strip_prefix(&root).unwrap_or(&path);
            let relative = relative.to_string_lossy().replace('\\', "/");
            if options.exclude.iter().any(|excluded| {
                pattern_matches(excluded, &name) || pattern_matches(excluded, &relative)
            }) {
                continue;
            }
            let file_type = match entry.file_type() {
                Ok(file_type) => file_type,
                Err(_) => continue,
            };
            let next = if file_type.is_dir() {
                path
            } else if file_type.is_symlink() && options.follow_symlinks {
                let Ok(canonical) = path.canonicalize() else {
                    continue;
                };
                if !canonical.starts_with(&root) || !canonical.is_dir() {
                    continue;
                }
                canonical
            } else {
                continue;
            };
            let canonical = next.canonicalize().unwrap_or(next);
            if visited.insert(canonical.clone()) {
                stack.push((canonical, depth + 1));
            }
        }
    }

    candidates.sort_by(|left, right| left.0.cmp(&right.0));
    let workspace_members = rust_workspace_members(&candidates);
    let mut projects = candidates
        .into_iter()
        .filter(|(path, kind, _)| *kind != ProjectKind::Rust || !workspace_members.contains(path))
        .map(|(path, kind, manifest)| identity(path, kind, manifest, options.git))
        .collect::<Vec<_>>();
    projects.sort_by(|left, right| left.canonical_path.cmp(&right.canonical_path));
    Ok(projects)
}

pub fn scan_business<F>(
    root: &Path,
    options: &DiscoveryOptions,
    parallel: usize,
    scan: F,
) -> Result<BusinessReport>
where
    F: Fn(&ProjectIdentity) -> Result<ProjectAnalysis> + Send + Sync + 'static,
{
    let canonical_root = root
        .canonicalize()
        .with_context(|| format!("discovery root does not exist: {}", root.display()))?;
    let projects = discover(&canonical_root, options)?;
    let discovered = projects.len();
    let scan = Arc::new(scan);
    let queue = Arc::new(Mutex::new(
        projects.into_iter().enumerate().collect::<Vec<_>>(),
    ));
    let output = Arc::new(Mutex::new(Vec::with_capacity(discovered)));
    let workers = parallel.max(1).min(discovered.max(1));

    std::thread::scope(|scope| {
        for _ in 0..workers {
            let scan = Arc::clone(&scan);
            let queue = Arc::clone(&queue);
            let output = Arc::clone(&output);
            scope.spawn(move || loop {
                let next = queue
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .pop();
                let Some((index, project)) = next else { break };
                let scan_result =
                    std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| scan(&project)));
                let result = match scan_result {
                    Ok(Ok(analysis)) => ProjectResult {
                        status: if analysis.findings.is_empty() {
                            ProjectStatus::Passed
                        } else {
                            ProjectStatus::Warning
                        },
                        project,
                        analysis: Some(analysis),
                        error: None,
                    },
                    Ok(Err(error)) => ProjectResult {
                        project,
                        status: ProjectStatus::Error,
                        analysis: None,
                        error: Some(format!("{error:#}")),
                    },
                    Err(_) => ProjectResult {
                        project,
                        status: ProjectStatus::Error,
                        analysis: None,
                        error: Some("project scanner panicked".to_owned()),
                    },
                };
                output
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .push((index, result));
            });
        }
    });

    let output = Arc::try_unwrap(output)
        .map_err(|_| anyhow::anyhow!("business workers retained the result collection"))?;
    let mut indexed = output
        .into_inner()
        .map_err(|_| anyhow::anyhow!("business result collection was poisoned"))?;
    indexed.sort_by_key(|(index, _)| *index);
    let projects = indexed
        .into_iter()
        .map(|(_, result)| result)
        .collect::<Vec<_>>();
    let business_findings = aggregate_findings(&projects);
    let summary = BusinessSummary {
        discovered,
        scanned: projects.len(),
        successful: projects
            .iter()
            .filter(|p| p.status == ProjectStatus::Passed)
            .count(),
        warnings: projects
            .iter()
            .filter(|p| p.status == ProjectStatus::Warning)
            .count(),
        errors: projects
            .iter()
            .filter(|p| p.status == ProjectStatus::Error)
            .count(),
    };
    Ok(BusinessReport {
        schema: "ferret.business/v1",
        root: canonical_root,
        projects,
        business_findings,
        summary,
    })
}

fn marker_at(path: &Path) -> Option<(ProjectKind, PathBuf)> {
    const MARKERS: &[(&str, ProjectKind)] = &[
        ("Cargo.toml", ProjectKind::Rust),
        ("package.json", ProjectKind::Node),
        ("pyproject.toml", ProjectKind::Python),
        ("go.mod", ProjectKind::Go),
        ("composer.json", ProjectKind::Php),
        ("Gemfile", ProjectKind::Ruby),
        ("mix.exs", ProjectKind::Elixir),
        ("pom.xml", ProjectKind::Java),
        ("build.gradle", ProjectKind::Java),
        ("build.gradle.kts", ProjectKind::Java),
    ];
    for (marker, kind) in MARKERS {
        let manifest = path.join(marker);
        if manifest.is_file() {
            return Some((*kind, manifest));
        }
    }
    let mut dotnet = std::fs::read_dir(path)
        .ok()?
        .flatten()
        .map(|entry| entry.path())
        .filter(|candidate| {
            candidate.is_file()
                && candidate
                    .extension()
                    .and_then(|ext| ext.to_str())
                    .is_some_and(|ext| matches!(ext, "sln" | "csproj"))
        })
        .collect::<Vec<_>>();
    dotnet.sort();
    dotnet
        .into_iter()
        .next()
        .map(|manifest| (ProjectKind::DotNet, manifest))
}

fn identity(
    path: PathBuf,
    kind: ProjectKind,
    manifest: PathBuf,
    with_git: bool,
) -> ProjectIdentity {
    let project_name = manifest_project_name(&manifest, kind).unwrap_or_else(|| {
        path.file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("project")
            .to_owned()
    });
    let (repository_root, git) = if with_git {
        git_metadata(&path).unwrap_or((None, None))
    } else {
        (None, None)
    };
    ProjectIdentity {
        canonical_path: path,
        project_kind: kind,
        project_name,
        project_manifest: manifest,
        repository_root,
        git,
    }
}

fn manifest_project_name(manifest: &Path, kind: ProjectKind) -> Option<String> {
    let text = std::fs::read_to_string(manifest).ok()?;
    match kind {
        ProjectKind::Node => serde_json::from_str::<serde_json::Value>(&text)
            .ok()?
            .get("name")?
            .as_str()
            .map(ToOwned::to_owned),
        ProjectKind::Rust => {
            let mut in_package = false;
            for line in text.lines() {
                let line = line.trim();
                if line.starts_with('[') {
                    in_package = line == "[package]";
                } else if in_package && line.starts_with("name") {
                    return quoted_value(line);
                }
            }
            None
        }
        _ => None,
    }
}

fn git_metadata(path: &Path) -> Option<(Option<PathBuf>, Option<GitMetadata>)> {
    let repo = git2::Repository::discover(path).ok()?;
    let root = repo.workdir().map(Path::to_path_buf);
    let branch = repo
        .head()
        .ok()
        .and_then(|head| head.shorthand().map(ToOwned::to_owned));
    let last_commit = repo
        .head()
        .ok()
        .and_then(|head| head.target())
        .map(|id| id.to_string());
    let dirty = repo
        .statuses(None)
        .map(|statuses| !statuses.is_empty())
        .unwrap_or(false);
    let remote = repo
        .find_remote("origin")
        .ok()
        .and_then(|remote| remote.url().map(ToOwned::to_owned));
    Some((
        root,
        Some(GitMetadata {
            branch,
            dirty,
            remote,
            last_commit,
            ahead: None,
            behind: None,
        }),
    ))
}

fn rust_workspace_members(candidates: &[(PathBuf, ProjectKind, PathBuf)]) -> BTreeSet<PathBuf> {
    let rust_paths = candidates
        .iter()
        .filter(|(_, kind, _)| *kind == ProjectKind::Rust)
        .map(|(path, _, _)| path.clone())
        .collect::<Vec<_>>();
    let mut members = BTreeSet::new();
    for (workspace, kind, manifest) in candidates {
        if *kind != ProjectKind::Rust {
            continue;
        }
        let Ok(text) = std::fs::read_to_string(manifest) else {
            continue;
        };
        let patterns = cargo_workspace_patterns(&text, "members");
        if patterns.is_empty() {
            continue;
        }
        let excludes = cargo_workspace_patterns(&text, "exclude");
        for candidate in &rust_paths {
            if candidate == workspace || !candidate.starts_with(workspace) {
                continue;
            }
            let relative = candidate.strip_prefix(workspace).unwrap_or(candidate);
            let relative = relative.to_string_lossy().replace('\\', "/");
            if patterns
                .iter()
                .any(|pattern| pattern_matches(pattern, &relative))
                && !excludes
                    .iter()
                    .any(|pattern| pattern_matches(pattern, &relative))
            {
                members.insert(candidate.clone());
            }
        }
    }
    members
}

fn cargo_workspace_patterns(text: &str, key: &str) -> Vec<String> {
    let mut in_workspace = false;
    let mut collecting = false;
    let mut value = String::new();
    for raw in text.lines() {
        let line = raw.split('#').next().unwrap_or("").trim();
        if line.starts_with('[') && !collecting {
            in_workspace = line == "[workspace]";
            continue;
        }
        if in_workspace && !collecting && line.starts_with(key) {
            if let Some((_, rhs)) = line.split_once('=') {
                value.push_str(rhs);
                collecting = !rhs.contains(']');
            }
        } else if collecting {
            value.push_str(line);
            collecting = !line.contains(']');
        }
        if !collecting && !value.is_empty() {
            break;
        }
    }
    let values = value
        .split_once('[')
        .map(|(_, values)| values)
        .unwrap_or(&value);
    let values = values
        .rsplit_once(']')
        .map(|(values, _)| values)
        .unwrap_or(values);
    values
        .split(',')
        .filter_map(|part| quoted_value(part.trim()))
        .collect()
}

fn quoted_value(text: &str) -> Option<String> {
    let (_, value) = text.split_once('=').unwrap_or(("", text));
    let value = value.trim();
    let quote = value.chars().next()?;
    if !matches!(quote, '\'' | '"') {
        return None;
    }
    let end = value[1..].find(quote)? + 1;
    Some(value[1..end].to_owned())
}

fn pattern_matches(pattern: &str, value: &str) -> bool {
    let pattern = pattern.trim_matches('/');
    let value = value.trim_matches('/');
    if !pattern.contains('*') {
        return value == pattern || value.contains(pattern);
    }
    let parts = pattern.split('*').collect::<Vec<_>>();
    let mut remainder = value;
    for (index, part) in parts.iter().enumerate() {
        if part.is_empty() {
            continue;
        }
        let Some(position) = remainder.find(part) else {
            return false;
        };
        if index == 0 && !pattern.starts_with('*') && position != 0 {
            return false;
        }
        remainder = &remainder[position + part.len()..];
    }
    pattern.ends_with('*') || remainder.is_empty()
}

fn matches_filters(relative: &Path, includes: &[String]) -> bool {
    if includes.is_empty() {
        return true;
    }
    let relative = relative.to_string_lossy().replace('\\', "/");
    includes
        .iter()
        .any(|pattern| pattern_matches(pattern, &relative))
}

fn aggregate_findings(projects: &[ProjectResult]) -> Vec<BusinessFinding> {
    let mut findings = Vec::new();
    let mut names: BTreeMap<&str, Vec<PathBuf>> = BTreeMap::new();
    let mut remotes: BTreeMap<&str, Vec<PathBuf>> = BTreeMap::new();
    let mut dirty = Vec::new();
    for result in projects {
        names
            .entry(&result.project.project_name)
            .or_default()
            .push(result.project.canonical_path.clone());
        if let Some(git) = &result.project.git {
            if git.dirty {
                dirty.push(result.project.canonical_path.clone());
            }
            if let Some(remote) = git.remote.as_deref() {
                remotes
                    .entry(remote)
                    .or_default()
                    .push(result.project.canonical_path.clone());
            }
        }
    }
    for (name, paths) in names.into_iter().filter(|(_, paths)| paths.len() > 1) {
        findings.push(BusinessFinding {
            severity: "warn".to_owned(),
            code: "duplicate_project_name".to_owned(),
            message: format!("{} projects share the name {name}", paths.len()),
            projects: paths,
        });
    }
    for (_, paths) in remotes.into_iter().filter(|(_, paths)| paths.len() > 1) {
        findings.push(BusinessFinding {
            severity: "warn".to_owned(),
            code: "duplicate_repository_remote".to_owned(),
            message: format!("{} projects share the same repository remote", paths.len()),
            projects: paths,
        });
    }
    if !dirty.is_empty() {
        findings.push(BusinessFinding {
            severity: "info".to_owned(),
            code: "uncommitted_changes".to_owned(),
            message: format!("{} projects have uncommitted changes", dirty.len()),
            projects: dirty,
        });
    }
    findings
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use std::sync::atomic::{AtomicUsize, Ordering};

    struct TempTree(PathBuf);
    impl TempTree {
        fn new() -> Self {
            let path =
                std::env::temp_dir().join(format!("ferret-business-{}", uuid::Uuid::new_v4()));
            fs::create_dir_all(&path).unwrap();
            Self(path)
        }
        fn project(&self, relative: &str, manifest: &str, content: &str) -> PathBuf {
            let path = self.0.join(relative);
            fs::create_dir_all(&path).unwrap();
            fs::write(path.join(manifest), content).unwrap();
            path
        }
    }
    impl Drop for TempTree {
        fn drop(&mut self) {
            let _ = fs::remove_dir_all(&self.0);
        }
    }

    #[test]
    fn discovers_multiple_projects_and_ignores_non_projects() {
        let tree = TempTree::new();
        tree.project("rusty", "Cargo.toml", "[package]\nname = \"rusty\"");
        tree.project("web", "package.json", r#"{"name":"web"}"#);
        fs::create_dir_all(tree.0.join("notes")).unwrap();
        let projects = discover(&tree.0, &DiscoveryOptions::default()).unwrap();
        assert_eq!(projects.len(), 2);
        assert_eq!(projects[0].project_name, "rusty");
        assert_eq!(projects[1].project_name, "web");
    }

    #[test]
    fn direct_target_requires_a_project_boundary() {
        let tree = TempTree::new();
        tree.project("child", "go.mod", "module child");
        let error = project_at(&tree.0, false).unwrap_err().to_string();
        assert!(error.contains("target_not_project"));
        assert!(project_at(&tree.0.join("child"), false).is_ok());
    }

    #[test]
    fn cargo_workspace_members_are_not_duplicate_projects() {
        let tree = TempTree::new();
        tree.project(
            "workspace",
            "Cargo.toml",
            "[workspace]\nmembers = [\"crates/*\"]",
        );
        tree.project(
            "workspace/crates/a",
            "Cargo.toml",
            "[package]\nname = \"a\"",
        );
        tree.project(
            "workspace/crates/b",
            "Cargo.toml",
            "[package]\nname = \"b\"",
        );
        tree.project(
            "workspace/tools/standalone",
            "Cargo.toml",
            "[package]\nname = \"standalone\"",
        );
        let projects = discover(&tree.0, &DiscoveryOptions::default()).unwrap();
        assert_eq!(projects.len(), 2);
        assert!(projects
            .iter()
            .any(|p| p.canonical_path.ends_with("workspace")));
        assert!(projects.iter().any(|p| p.project_name == "standalone"));
    }

    #[test]
    fn cargo_workspace_excludes_remain_independent_projects() {
        let tree = TempTree::new();
        tree.project(
            "workspace",
            "Cargo.toml",
            "[workspace]\nmembers = [\"crates/*\"]\nexclude = [\"crates/tool\"]",
        );
        tree.project(
            "workspace/crates/member",
            "Cargo.toml",
            "[package]\nname = \"member\"",
        );
        tree.project(
            "workspace/crates/tool",
            "Cargo.toml",
            "[package]\nname = \"tool\"",
        );
        let projects = discover(&tree.0, &DiscoveryOptions::default()).unwrap();
        assert_eq!(projects.len(), 2);
        assert!(projects
            .iter()
            .any(|project| project.project_name == "tool"));
    }

    #[test]
    fn exclusions_depth_and_kind_are_deterministic() {
        let tree = TempTree::new();
        tree.project(
            "target/hidden",
            "Cargo.toml",
            "[package]\nname = \"hidden\"",
        );
        tree.project("a/b/deep", "go.mod", "module deep");
        tree.project("node", "package.json", r#"{"name":"node"}"#);
        let shallow = DiscoveryOptions {
            max_depth: 1,
            ..Default::default()
        };
        assert_eq!(discover(&tree.0, &shallow).unwrap().len(), 1);
        let rust_only = DiscoveryOptions {
            project_kind: Some(ProjectKind::Rust),
            ..Default::default()
        };
        assert!(discover(&tree.0, &rust_only).unwrap().is_empty());
    }

    #[cfg(unix)]
    #[test]
    fn symlinks_are_not_followed_by_default_and_cannot_escape_root() {
        use std::os::unix::fs::symlink;
        let tree = TempTree::new();
        let outside = TempTree::new();
        outside.project("project", "go.mod", "module outside");
        symlink(outside.0.join("project"), tree.0.join("linked")).unwrap();
        symlink(tree.0.join("missing"), tree.0.join("broken")).unwrap();
        assert!(discover(&tree.0, &DiscoveryOptions::default())
            .unwrap()
            .is_empty());
        let followed = DiscoveryOptions {
            follow_symlinks: true,
            ..Default::default()
        };
        assert!(discover(&tree.0, &followed).unwrap().is_empty());
    }

    #[cfg(unix)]
    #[test]
    fn inaccessible_directories_do_not_hide_sibling_projects() {
        use std::os::unix::fs::PermissionsExt;
        let tree = TempTree::new();
        let blocked = tree.project("blocked/project", "go.mod", "module blocked");
        let blocked_parent = blocked.parent().unwrap();
        std::fs::set_permissions(blocked_parent, std::fs::Permissions::from_mode(0o000)).unwrap();
        tree.project("visible", "go.mod", "module visible");

        let projects = discover(&tree.0, &DiscoveryOptions::default()).unwrap();
        std::fs::set_permissions(blocked_parent, std::fs::Permissions::from_mode(0o700)).unwrap();
        assert!(projects
            .iter()
            .any(|project| project.canonical_path.ends_with("visible")));
    }

    #[test]
    fn scan_failures_are_isolated_and_results_remain_sorted() {
        let tree = TempTree::new();
        tree.project("c", "go.mod", "module c");
        tree.project("a", "go.mod", "module a");
        tree.project("b", "go.mod", "module b");
        tree.project("d", "go.mod", "module d");
        let calls = Arc::new(AtomicUsize::new(0));
        let scan_calls = Arc::clone(&calls);
        let report = scan_business(&tree.0, &DiscoveryOptions::default(), 3, move |project| {
            scan_calls.fetch_add(1, Ordering::SeqCst);
            if matches!(project.project_name.as_str(), "b" | "c") {
                bail!("broken project")
            }
            Ok(ProjectAnalysis {
                files_scanned: 1,
                findings: Vec::new(),
            })
        })
        .unwrap();
        assert_eq!(calls.load(Ordering::SeqCst), 4);
        assert_eq!(report.summary.errors, 2);
        let names = report
            .projects
            .iter()
            .map(|p| p.project.project_name.as_str())
            .collect::<Vec<_>>();
        assert_eq!(names, vec!["a", "b", "c", "d"]);
        assert_eq!(report.exit_code(), 2);
    }

    #[test]
    fn scanner_panics_are_isolated() {
        let tree = TempTree::new();
        tree.project("a", "go.mod", "module a");
        tree.project("b", "go.mod", "module b");
        let report = scan_business(&tree.0, &DiscoveryOptions::default(), 2, |project| {
            if project.project_name == "a" {
                panic!("malformed input triggered scanner bug");
            }
            Ok(ProjectAnalysis {
                files_scanned: 1,
                findings: Vec::new(),
            })
        })
        .unwrap();
        assert_eq!(report.summary.errors, 1);
        assert_eq!(report.summary.successful, 1);
    }

    #[test]
    fn no_projects_is_a_successful_report() {
        let tree = TempTree::new();
        let report =
            scan_business(&tree.0, &DiscoveryOptions::default(), 4, |_| unreachable!()).unwrap();
        assert_eq!(report.summary.discovered, 0);
        assert_eq!(report.exit_code(), 0);
    }
}

//! 3form-backed animated result trails for interactive Ferret commands.

use form3::term::TermInfo;
use form3::{Aura, GrowthTrack, Mode};
use std::io::{self, Write};
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::Duration;

const FRAME_DELAY: Duration = Duration::from_millis(18);
const ANIMATION_STEPS: usize = 6;
static ENABLED: AtomicBool = AtomicBool::new(false);
static MACHINE: AtomicBool = AtomicBool::new(false);

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct ChaseFont {
    round: usize,
    ferret: [&'static str; 3],
    rabbit: [&'static str; 3],
}

/// Six successive font mutations. Each round retains a recognisable species
/// silhouette while increasing expression and motion differentiation.
const FONT_ROUNDS: [ChaseFont; 6] = [
    ChaseFont {
        round: 1,
        ferret: ["~o>", "~~o>", "~o>>"],
        rabbit: ["(o)", "(O)", "(!)"],
    },
    ChaseFont {
        round: 2,
        ferret: ["~(o)>", "~~(^)>", "~(>)>>"],
        rabbit: ["/(o)\\", "/(^)\\", "/(!)\\"],
    },
    ChaseFont {
        round: 3,
        ferret: ["~(o.o)>", "~~(^.o)>", "~(>.<)>>"],
        rabbit: ["/(o.o)\\", "/(^.^)\\", "/(!.!)\\"],
    },
    ChaseFont {
        round: 4,
        ferret: ["~(•.•)>", "~~(ᵔ.•)>", "~(>.<)>>"],
        rabbit: ["/(•.•)\\", "/(ᵔ.ᵔ)\\", "/(!.!)\\"],
    },
    ChaseFont {
        round: 5,
        ferret: ["~(•ᴥ•)>", "~~(ᵔᴥᵔ)>", "~(•̀ᴥ•́)>>"],
        rabbit: ["/(•×•)\\", "/(O×o)\\", "/(˃×˂)\\"],
    },
    ChaseFont {
        round: 6,
        ferret: ["≈~(•ᴥ•)>", "≈~~(ᵔᴥᵔ)>", "≈~(•̀ᴥ•́)>>"],
        rabbit: ["/(•×•)\\", "/(O×O)\\", "/(˃×˂)\\"],
    },
];

#[derive(Debug, Clone, Copy)]
struct Evaluation {
    font: ChaseFont,
    score: usize,
    rounds: usize,
}

/// Enable animated UI output after CLI mode negotiation. Machine/JSON output
/// remains byte-stable, as required by the 3form environment contract.
pub fn configure(machine_output: bool) {
    let explicitly_disabled = std::env::var("FERRET_ANIMATION")
        .ok()
        .is_some_and(|value| matches!(value.as_str(), "0" | "false" | "FALSE"));
    let mode = Mode::auto();
    MACHINE.store(machine_output || mode == Mode::Machine, Ordering::Relaxed);
    ENABLED.store(
        !machine_output && !explicitly_disabled && mode == Mode::Ui && TermInfo::detect().is_tty,
        Ordering::Relaxed,
    );
}

/// Shared sink used by every human-facing `println!` in the Ferret CLI.
pub fn print_line(text: &str) {
    if !ENABLED.load(Ordering::Relaxed) {
        if MACHINE.load(Ordering::Relaxed) {
            std::println!("{}", strip_ansi(text));
        } else {
            std::println!("{text}");
        }
        return;
    }

    if text.is_empty() {
        std::println!();
        return;
    }

    for line in text.split('\n') {
        if line.is_empty() {
            std::println!();
        } else if animate_line(line).is_err() {
            // Output failures must never turn decorative animation into a
            // command failure. Fall back to the original result line.
            std::println!("{line}");
        }
    }
}

fn animate_line(line: &str) -> io::Result<()> {
    let term = TermInfo::detect();
    let evaluation = evaluate_rounds(0, None);
    debug_assert_eq!(evaluation.rounds, FONT_ROUNDS.len());
    let font = evaluation.font;
    let visible_total = visible_len(line).max(1);
    let aura = Aura::new((92, 48, 25), (196, 126, 90), (255, 230, 211));
    let track = GrowthTrack::new(3).with_glyphs('·', '·', '✦', '›');
    let mut stdout = io::stdout().lock();

    for step in 0..ANIMATION_STEPS {
        let progress = (step + 1) as f32 / ANIMATION_STEPS as f32;
        let pose = step % font.ferret.len();
        let revealed = visible_prefix(line, ((visible_total as f32) * progress).ceil() as usize);
        let remaining = visible_total.saturating_sub(visible_len(&revealed));
        let ferret = aura.paint(font.ferret[pose], progress, term.color_support);
        let rabbit = aura.paint(font.rabbit[pose], 1.0 - progress, term.color_support);
        write!(
            stdout,
            "\r\x1b[2K{revealed}{} {ferret}{}{rabbit}",
            track.render(progress),
            " ".repeat(remaining + 1)
        )?;
        stdout.flush()?;
        std::thread::sleep(FRAME_DELAY);
    }

    writeln!(
        stdout,
        "\r\x1b[2K{line} ··· {}  {}",
        aura.paint(font.ferret[2], 1.0, term.color_support),
        aura.paint(font.rabbit[2], 0.0, term.color_support)
    )?;
    stdout.flush()
}

fn evaluate_rounds(index: usize, best: Option<Evaluation>) -> Evaluation {
    if index == FONT_ROUNDS.len() {
        return best.unwrap_or(Evaluation {
            font: FONT_ROUNDS[0],
            score: 0,
            rounds: 0,
        });
    }
    let font = FONT_ROUNDS[index];
    let candidate = Evaluation {
        font,
        score: score_font(&font),
        rounds: index + 1,
    };
    let best = match best {
        Some(current) if current.score >= candidate.score => current,
        _ => candidate,
    };
    evaluate_rounds(index + 1, Some(best))
}

fn score_font(font: &ChaseFont) -> usize {
    let unique_ferrets = font
        .ferret
        .iter()
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    let unique_rabbits = font
        .rabbit
        .iter()
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    let species = usize::from(font.ferret.iter().all(|pose| pose.contains('~')))
        + usize::from(
            font.rabbit
                .iter()
                .all(|pose| pose.starts_with('/') && pose.ends_with('\\')),
        );
    let expression = font
        .ferret
        .iter()
        .chain(font.rabbit.iter())
        .flat_map(|pose| pose.chars())
        .filter(|glyph| matches!(glyph, '•' | 'ᴥ' | 'ᵔ' | '˃' | '˂' | '×' | '̀' | '́'))
        .count();
    unique_ferrets * 3 + unique_rabbits * 3 + species * 5 + expression + font.round
}

fn visible_len(text: &str) -> usize {
    let mut count = 0;
    let mut bytes = text.as_bytes().iter().copied().peekable();
    while let Some(byte) = bytes.next() {
        if byte == 0x1b && bytes.peek() == Some(&b'[') {
            bytes.next();
            for code in bytes.by_ref() {
                if code.is_ascii_alphabetic() {
                    break;
                }
            }
        } else if byte & 0b1100_0000 != 0b1000_0000 {
            count += 1;
        }
    }
    count
}

fn visible_prefix(text: &str, limit: usize) -> String {
    let mut output = String::new();
    let mut visible = 0;
    let mut chars = text.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch == '\x1b' && chars.peek() == Some(&'[') {
            output.push(ch);
            while let Some(code) = chars.next() {
                output.push(code);
                if code.is_ascii_alphabetic() {
                    break;
                }
            }
            continue;
        }
        if visible >= limit {
            break;
        }
        output.push(ch);
        visible += 1;
    }
    if output.contains("\x1b[") {
        output.push_str("\x1b[0m");
    }
    output
}

fn strip_ansi(text: &str) -> String {
    let mut output = String::with_capacity(text.len());
    let mut chars = text.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch == '\x1b' && chars.peek() == Some(&'[') {
            for code in chars.by_ref() {
                if code.is_ascii_alphabetic() {
                    break;
                }
            }
        } else {
            output.push(ch);
        }
    }
    output
}

#[cfg(test)]
mod tests {
    use super::*;
    use form3::term::ColorSupport;

    #[test]
    fn six_recursive_rounds_select_the_most_expressive_font() {
        let evaluation = evaluate_rounds(0, None);
        assert_eq!(evaluation.rounds, 6);
        assert_eq!(evaluation.font.round, 6);
        assert!(evaluation.font.ferret[2].contains('ᴥ'));
        assert!(evaluation.font.rabbit[2].contains('˃'));
    }

    #[test]
    fn selected_font_has_three_mutated_poses_per_animal() {
        let font = evaluate_rounds(0, None).font;
        assert_eq!(
            font.ferret
                .iter()
                .collect::<std::collections::BTreeSet<_>>()
                .len(),
            3
        );
        assert_eq!(
            font.rabbit
                .iter()
                .collect::<std::collections::BTreeSet<_>>()
                .len(),
            3
        );
    }

    #[test]
    fn ansi_aware_reveal_never_splits_style_sequences() {
        let styled = "\x1b[32mFERRET\x1b[0m result";
        assert_eq!(visible_len(styled), 13);
        let prefix = visible_prefix(styled, 3);
        assert!(prefix.contains("\x1b[32mFER"));
        assert!(prefix.ends_with("\x1b[0m"));
    }

    #[test]
    fn machine_cleanup_removes_ansi_without_losing_text() {
        assert_eq!(strip_ansi("\x1b[32mFERRET\x1b[0m result"), "FERRET result");
    }

    #[test]
    fn threeform_track_never_preprints_future_cells() {
        let track = GrowthTrack::new(8).with_glyphs('·', '·', '✦', '›');
        assert!(track.render(0.25).chars().count() < track.render(0.75).chars().count());
    }

    #[test]
    fn no_color_fonts_are_still_legible() {
        let font = evaluate_rounds(0, None).font;
        let painted = Aura::mystic().paint(font.ferret[0], 0.5, ColorSupport::NoColor);
        assert_eq!(painted, font.ferret[0]);
        assert!(!painted.contains("\x1b["));
    }
}

use anyhow::{Context, Result};
mod business;
mod chase;
mod progress_compat;
mod style_compat;

// Route every human-facing Ferret result line through the shared 3form chase.
// The sink is a plain println in machine/JSON/non-TTY modes.
macro_rules! println {
    () => {
        crate::chase::print_line("")
    };
    ($($arg:tt)*) => {
        crate::chase::print_line(&format!($($arg)*))
    };
}

use chrono::Utc;
use clap::{Parser, Subcommand};
use crate::style_compat::{style, Style};
use ferret_core::{PredictedFinding, RepoProfile, ReviewSnapshot, SnapshotId, TeacherKind};
use ferret_infer::RetrievalPredictor;
use ferret_ingest::{extract_hunks, hunks_from_unified_diff, stable_hunk_id};
use ferret_route::{Route, Router, RouterConfig};
use ferret_store::Store;
use crate::progress_compat::{hunk_progress, spinner};
use std::path::{Path, PathBuf};
use tracing::info;

use business::{
    BusinessReport, DiscoveryOptions, FindingSummary, ProjectAnalysis, ProjectIdentity,
    ProjectKind, ProjectStatus,
};

const LOGO: &str = include_str!("../../../.brandi/assets/logo.ansi");
const TAGLINE: &str = "Review memory that learns.";

#[derive(Parser)]
#[command(
    name = "ferret",
    about = "Deterministic project scanner",
    long_about = "ferret requires a project target; ferret business discovers projects within an environment and scans them independently."
)]
struct Cli {
    #[arg(short, long, default_value = "ferret.db")]
    database: PathBuf,

    /// Scan one coherent project (defaults to the current directory).
    #[arg(value_name = "TARGET")]
    target: Option<PathBuf>,

    /// Emit machine-readable JSON for project and business scans.
    #[arg(long, global = true)]
    json: bool,

    #[command(subcommand)]
    command: Option<Command>,
}

#[derive(Subcommand)]
enum Command {
    /// Discover and independently scan coherent projects beneath ROOT.
    Business {
        /// Discovery boundary (defaults to $HOME).
        #[arg(value_name = "ROOT")]
        root: Option<PathBuf>,
        /// Maximum directory depth beneath ROOT.
        #[arg(long, default_value_t = 12)]
        max_depth: usize,
        /// Include only matching relative project paths (`*` is supported).
        #[arg(long)]
        include: Vec<String>,
        /// Exclude matching directory names or paths (`*` is supported).
        #[arg(long)]
        exclude: Vec<String>,
        /// Disable the built-in build/cache/vendor exclusions.
        #[arg(long)]
        no_default_excludes: bool,
        /// Discover only one kind: rust, node, python, go, php, ruby, elixir, java, dotnet.
        #[arg(long)]
        project_kind: Option<String>,
        /// Maximum simultaneous project scans.
        #[arg(long)]
        parallel: Option<usize>,
        /// Do not collect Git repository metadata.
        #[arg(long)]
        no_git: bool,
        /// Follow in-boundary directory symlinks with canonical loop detection.
        #[arg(long)]
        follow_symlinks: bool,
    },
    /// Print the Ferret logo and brand mark.
    Logo,
    /// Initialize the local Ferret database.
    Init,
    /// Register or update a repository profile.
    Register {
        #[arg(long)]
        slug: String,
    },
    /// Capture a review snapshot from a git diff.
    Snapshot {
        #[arg(long)]
        repo: String,
        #[arg(long)]
        base: String,
        #[arg(long)]
        head: String,
        #[arg(long)]
        path: Option<PathBuf>,
        #[arg(long)]
        diff: Option<PathBuf>,
        #[arg(long)]
        pr: Option<u32>,
    },
    /// Show corpus statistics.
    Stats,
    /// Predict findings for a snapshot using retrieval.
    Predict {
        #[arg(long)]
        repo: String,
        #[arg(long)]
        base: String,
        #[arg(long)]
        head: String,
        #[arg(long)]
        path: Option<PathBuf>,
        #[arg(long)]
        diff: Option<PathBuf>,
    },
    /// Show routing decisions for predicted findings.
    Route {
        #[arg(long)]
        repo: String,
        #[arg(long)]
        base: String,
        #[arg(long)]
        head: String,
        #[arg(long)]
        path: Option<PathBuf>,
        #[arg(long)]
        diff: Option<PathBuf>,
    },
    /// Track a CodeRabbit review on the target directory (or pwd) and learn from it.
    Track {
        /// Target directory to review (defaults to current directory)
        #[arg(long, value_name = "PATH")]
        path: Option<PathBuf>,
        /// Also treat as positional for convenience: ferret track ./mydir
        #[arg(value_name = "DIR")]
        dir: Option<PathBuf>,
    },
    /// Convert recent Ferret findings into Dreamseq .dreams entries in the target directory.
    Dream {
        /// Target directory whose .dreams file will be written (defaults to current directory)
        #[arg(long, value_name = "PATH")]
        path: Option<PathBuf>,
        /// Positional directory for convenience: ferret dream ./mydir
        #[arg(value_name = "DIR")]
        dir: Option<PathBuf>,
        /// Maximum number of recent findings to convert (default 20)
        #[arg(long, default_value = "20")]
        limit: usize,
        /// Also write a legacy .dream file (single file) alongside .dreams/active.dreams
        #[arg(long)]
        legacy: bool,
    },
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    let cli = Cli::parse();
    chase::configure(cli.json);
    let db = format!("sqlite:{}", cli.database.display());

    if let Some(target) = cli.target.as_deref() {
        let exit = run_project_command(target, cli.json);
        std::process::exit(exit.into());
    }

    let Some(command) = cli.command else {
        let target = std::env::current_dir().context("resolve current directory")?;
        let exit = run_project_command(&target, cli.json);
        std::process::exit(exit.into());
    };

    match command {
        Command::Business {
            root,
            max_depth,
            include,
            exclude,
            no_default_excludes,
            project_kind,
            parallel,
            no_git,
            follow_symlinks,
        } => {
            let root = match root.or_else(home_directory) {
                Some(root) => root,
                None => {
                    eprintln!(
                        "ERROR business_invocation_failed\nreason: HOME is not set; provide ROOT"
                    );
                    std::process::exit(3);
                }
            };
            let project_kind = match project_kind {
                Some(kind) => match ProjectKind::parse(&kind) {
                    Some(kind) => Some(kind),
                    None => {
                        eprintln!("ERROR business_invocation_failed\nreason: unknown project kind `{kind}`");
                        std::process::exit(3);
                    }
                },
                None => None,
            };
            let mut options = DiscoveryOptions {
                max_depth,
                include,
                exclude: if no_default_excludes {
                    Vec::new()
                } else {
                    business::DEFAULT_EXCLUSIONS
                        .iter()
                        .map(|value| (*value).to_owned())
                        .collect()
                },
                project_kind,
                follow_symlinks,
                git: !no_git,
            };
            options.exclude.extend(exclude);
            let parallel = parallel.unwrap_or_else(|| {
                std::thread::available_parallelism()
                    .map(usize::from)
                    .unwrap_or(1)
            });
            if parallel == 0 {
                eprintln!(
                    "ERROR business_invocation_failed\nreason: --parallel must be at least 1"
                );
                std::process::exit(3);
            }
            match business::scan_business(&root, &options, parallel, scan_project) {
                Ok(report) => {
                    if cli.json {
                        println!("{}", serde_json::to_string_pretty(&report)?);
                    } else {
                        print_business_report(&report);
                    }
                    std::process::exit(report.exit_code().into());
                }
                Err(error) => {
                    eprintln!("ERROR business_discovery_failed\nreason: {error:#}");
                    std::process::exit(3);
                }
            }
        }
        Command::Logo => {
            print_logo();
        }
        Command::Init => {
            print_logo();
            let spinner = spinner("Opening database");
            let _store = Store::open(&db).await?;
            spinner.finish_with_message(style("Database ready").green().to_string());
            info!(path = %cli.database.display(), "database initialized");
        }
        Command::Register { slug } => {
            let spinner = spinner("Registering repository");
            let store = Store::open(&db).await?;
            store.upsert_repo(&RepoProfile::new(&slug)).await?;
            spinner.finish_with_message(style("Repository registered").green().to_string());
            println!("{} {}", style("→").cyan(), style(slug).bold());
        }
        Command::Snapshot {
            repo,
            base,
            head,
            path,
            diff,
            pr,
        } => {
            let extract_spinner = spinner("Extracting hunks");
            let store = Store::open(&db).await?;
            let repo_id = store.upsert_repo(&RepoProfile::new(&repo)).await?;
            let hunks = load_hunks(path.as_deref(), diff.as_deref(), &base, &head)?;
            extract_spinner
                .finish_with_message(format!("{} hunks extracted", style(hunks.len()).bold()));

            let save_spinner = spinner("Saving snapshot");
            let snapshot = ReviewSnapshot {
                id: SnapshotId::new(),
                repo_id,
                pr_number: pr,
                base_sha: base,
                head_sha: head,
                hunks,
                teachers: vec![
                    TeacherKind::GitHub,
                    TeacherKind::Sarif,
                    TeacherKind::CodeRabbit,
                ],
                captured_at: Utc::now(),
            };
            store.save_snapshot(&snapshot).await?;
            save_spinner.finish_with_message(style("Snapshot saved").green().to_string());
            print_snapshot_summary(&snapshot);
        }
        Command::Stats => {
            let spinner = spinner("Counting corpus");
            let store = Store::open(&db).await?;
            let stats = store.corpus_stats().await?;
            spinner.finish_and_clear();
            print_stats(&stats);
        }
        Command::Predict {
            repo,
            base,
            head,
            path,
            diff,
        } => {
            let store = Store::open(&db).await?;
            let repo_id = store.upsert_repo(&RepoProfile::new(&repo)).await?;
            let hunks = load_hunks(path.as_deref(), diff.as_deref(), &base, &head)?;
            let snapshot = ReviewSnapshot {
                id: SnapshotId::new(),
                repo_id,
                pr_number: None,
                base_sha: base,
                head_sha: head,
                hunks,
                teachers: vec![TeacherKind::Ferret],
                captured_at: Utc::now(),
            };

            let pb = hunk_progress(snapshot.hunks.len(), "Predicting findings").await;
            let predictions = RetrievalPredictor::predict(&store, &snapshot).await?;
            pb.finish_and_clear();
            print_predictions(&predictions);
        }
        Command::Route {
            repo,
            base,
            head,
            path,
            diff,
        } => {
            let store = Store::open(&db).await?;
            let repo_id = store.upsert_repo(&RepoProfile::new(&repo)).await?;
            let hunks = load_hunks(path.as_deref(), diff.as_deref(), &base, &head)?;
            let snapshot = ReviewSnapshot {
                id: SnapshotId::new(),
                repo_id,
                pr_number: None,
                base_sha: base,
                head_sha: head,
                hunks,
                teachers: vec![TeacherKind::Ferret],
                captured_at: Utc::now(),
            };

            let pb = hunk_progress(snapshot.hunks.len(), "Routing findings").await;
            let predictions = RetrievalPredictor::predict(&store, &snapshot).await?;
            pb.finish_and_clear();
            let router = Router::new(RouterConfig::default());
            let routed = router.route(predictions);
            print_routed(&routed);
        }
        Command::Track { path, dir } => {
            let target = resolve_track_target(path.or(dir));
            run_track(&db, &target).await?;
        }
        Command::Dream {
            path,
            dir,
            limit,
            legacy,
        } => {
            let target = resolve_track_target(path.or(dir));
            run_dream(&db, &target, limit, legacy).await?;
        }
    }

    Ok(())
}

fn home_directory() -> Option<PathBuf> {
    std::env::var_os("HOME")
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
}

fn run_project_command(target: &Path, json: bool) -> u8 {
    let project = match business::project_at(target, true) {
        Ok(project) => project,
        Err(error) => {
            eprintln!("ERROR {error:#}");
            return 3;
        }
    };
    match scan_project(&project) {
        Ok(analysis) => {
            let exit = u8::from(!analysis.findings.is_empty());
            if json {
                let output = serde_json::json!({
                    "schema": "ferret.project/v1",
                    "project": project,
                    "analysis": analysis,
                });
                match serde_json::to_string_pretty(&output) {
                    Ok(output) => println!("{output}"),
                    Err(error) => {
                        eprintln!("ERROR serialize_project_report\nreason: {error}");
                        return 3;
                    }
                }
            } else {
                println!("FERRET\n");
                println!("Project:  {}", project.project_name);
                println!("Path:     {}", project.canonical_path.display());
                println!("Kind:     {}", project.project_kind);
                println!("Files:    {}", analysis.files_scanned);
                println!("Findings: {}", analysis.findings.len());
                if !analysis.findings.is_empty() {
                    println!("\nPROJECT FINDINGS\n");
                    for finding in &analysis.findings {
                        println!(
                            "{}  {}",
                            finding.severity.to_ascii_uppercase(),
                            finding.message
                        );
                    }
                }
            }
            exit
        }
        Err(error) => {
            eprintln!(
                "ERROR project_scan_failed\ntarget: {}\nreason: {error:#}",
                project.canonical_path.display()
            );
            2
        }
    }
}

fn scan_project(project: &ProjectIdentity) -> Result<ProjectAnalysis> {
    let manifest = std::fs::read_to_string(&project.project_manifest)
        .with_context(|| format!("read manifest {}", project.project_manifest.display()))?;
    if manifest.trim().is_empty() {
        anyhow::bail!("manifest is empty: {}", project.project_manifest.display());
    }
    if project.project_kind == ProjectKind::Node {
        serde_json::from_str::<serde_json::Value>(&manifest)
            .with_context(|| format!("parse manifest {}", project.project_manifest.display()))?;
    }

    let hunks = collect_hunks_for_track(&project.canonical_path)?;
    let snapshot = ReviewSnapshot {
        id: SnapshotId::new(),
        repo_id: ferret_core::RepoId::from_slug(&project.canonical_path.to_string_lossy()),
        pr_number: None,
        base_sha: "scan-base".into(),
        head_sha: "scan-head".into(),
        hunks,
        teachers: vec![TeacherKind::CodeRabbit, TeacherKind::Ferret],
        captured_at: Utc::now(),
    };
    let files_by_hunk = snapshot
        .hunks
        .iter()
        .map(|hunk| (hunk.id.as_str(), hunk.file_path.as_str()))
        .collect::<std::collections::HashMap<_, _>>();
    let mut findings = coderabbit_review(&snapshot)
        .into_iter()
        .map(|finding| FindingSummary {
            category: format!("{:?}", finding.category).to_ascii_lowercase(),
            severity: format!("{:?}", finding.severity).to_ascii_lowercase(),
            message: finding.message,
            rule_id: finding.rule_id,
            file: finding
                .hunk_id
                .as_deref()
                .and_then(|id| files_by_hunk.get(id).copied())
                .map(ToOwned::to_owned),
        })
        .collect::<Vec<_>>();
    findings.sort_by(|left, right| {
        left.file
            .cmp(&right.file)
            .then_with(|| left.rule_id.cmp(&right.rule_id))
            .then_with(|| left.message.cmp(&right.message))
    });
    Ok(ProjectAnalysis {
        files_scanned: snapshot.hunks.len(),
        findings,
    })
}

fn print_business_report(report: &BusinessReport) {
    println!("FERRET BUSINESS\n");
    println!("Root: {}\n", report.root.display());
    println!("Projects discovered: {}", report.summary.discovered);
    println!("Projects scanned:    {}", report.summary.scanned);
    println!("Successful:          {}", report.summary.successful);
    println!("Warnings:            {}", report.summary.warnings);
    println!("Errors:              {}", report.summary.errors);
    println!("\nPROJECTS\n");
    for result in &report.projects {
        let (symbol, outcome) = match result.status {
            ProjectStatus::Passed => ("✓", "PASS".to_owned()),
            ProjectStatus::Warning => (
                "⚠",
                format!(
                    "{} findings",
                    result
                        .analysis
                        .as_ref()
                        .map_or(0, |analysis| analysis.findings.len())
                ),
            ),
            ProjectStatus::Error => ("✗", "ERROR".to_owned()),
        };
        println!(
            "{symbol} {:<20} {:<8} {outcome}",
            result.project.project_name, result.project.project_kind
        );
        if let Some(error) = &result.error {
            println!("  {}", style(error).red());
        }
    }
    if !report.business_findings.is_empty() {
        println!("\nBUSINESS FINDINGS\n");
        for finding in &report.business_findings {
            println!(
                "{:<5} {}",
                finding.severity.to_ascii_uppercase(),
                finding.message
            );
        }
    }
}

fn resolve_track_target(input: Option<PathBuf>) -> PathBuf {
    match input {
        Some(p) if p.as_os_str() == "." || p.as_os_str().is_empty() => {
            std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
        }
        Some(p) => p,
        None => std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")),
    }
}

async fn run_track(db: &str, target: &Path) -> Result<()> {
    use ferret_core::{Category, Severity};

    print_logo();
    println!(
        "{} {}",
        style("Tracking CodeRabbit review on:").cyan().bold(),
        style(target.display()).bold()
    );

    // Resolve canonical target and slug
    let canonical_target = target
        .canonicalize()
        .unwrap_or_else(|_| target.to_path_buf());
    let slug = infer_slug(&canonical_target);
    println!("{} {}", style("→ slug:").dim(), style(&slug).bold());

    let scan_spinner = spinner("Scanning environment");
    let store = Store::open(db).await?;
    let repo_id = store.upsert_repo(&RepoProfile::new(&slug)).await?;

    // Collect hunks: try git diff first if target is a git repo, else scan files
    let hunks = collect_hunks_for_track(&canonical_target)?;
    scan_spinner.finish_with_message(format!(
        "{} files/hunks collected from {}",
        style(hunks.len()).bold(),
        style(canonical_target.display()).dim()
    ));

    if hunks.is_empty() {
        println!("{}", style("No files found to review.").yellow());
        return Ok(());
    }

    // Build snapshot that will be tracked
    let snapshot = ReviewSnapshot {
        id: SnapshotId::new(),
        repo_id,
        pr_number: None,
        base_sha: "track-base".into(),
        head_sha: "track-head".into(),
        hunks: hunks.clone(),
        teachers: vec![TeacherKind::CodeRabbit, TeacherKind::Ferret],
        captured_at: Utc::now(),
    };
    store.save_snapshot(&snapshot).await?;
    info!(snapshot = %snapshot.id.0, hunks = hunks.len(), "snapshot saved for track");

    // Conduct CodeRabbit review (heuristic + stub teacher) while Ferret tracks
    let review_spinner = spinner("Running CodeRabbit review (Ferret tracking)");
    let findings = coderabbit_review(&snapshot);
    review_spinner.finish_with_message(format!(
        "{} CodeRabbit findings",
        style(findings.len()).bold()
    ));

    // Ferret learns: persist findings and learn environment + review habits
    let learn_spinner = spinner("Ferret learning environment & review habits");
    let mut env_profile = RepoProfile::new(&slug);
    // Learn environment: languages, file counts
    let mut lang_counts: std::collections::HashMap<String, usize> =
        std::collections::HashMap::new();
    for h in &hunks {
        let lang = h.language.clone().unwrap_or_else(|| "unknown".into());
        *lang_counts.entry(lang).or_insert(0) += 1;
    }
    // Learn review habits: category distribution and severity
    let mut cat_counts: std::collections::HashMap<Category, usize> =
        std::collections::HashMap::new();
    let mut sev_counts: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
    for f in &findings {
        store.save_finding(f).await?;
        *cat_counts.entry(f.category).or_insert(0) += 1;
        *sev_counts.entry(format!("{:?}", f.severity)).or_insert(0) += 1;
    }

    // Update strictness: higher strictness for categories CodeRabbit flagged often
    let total = findings.len().max(1) as f32;
    for (cat, count) in &cat_counts {
        let strictness = (*count as f32 / total).clamp(0.0, 1.0);
        env_profile.strictness.insert(*cat, strictness);
    }
    // Teacher reliability: CodeRabbit observed
    env_profile
        .teacher_reliability
        .insert("coderabbit".into(), 0.85);
    env_profile
        .teacher_reliability
        .insert("ferret".into(), 0.75);
    env_profile.total_snapshots = 1;
    env_profile.total_findings = findings.len() as u64;

    // Merge with existing profile if present: load previous and increment
    // (upsert will replace, so we fetch existing via stats and previous profile)
    // For simplicity, we add to the newly learned profile and upsert
    store.upsert_repo(&env_profile).await?;
    learn_spinner.finish_with_message(style("Ferret updated").green().to_string());

    // Print summary
    println!();
    let header = Style::new().bold().underlined();
    println!("{}", header.apply_to("Track summary"));
    println!(
        "  {} {}",
        style("target:").cyan().bold(),
        style(canonical_target.display()).bold()
    );
    println!(
        "  {} {}",
        style("hunks:").cyan().bold(),
        style(hunks.len()).bold()
    );
    println!(
        "  {} {}",
        style("findings:").cyan().bold(),
        style(findings.len()).bold()
    );
    if !lang_counts.is_empty() {
        let langs = lang_counts
            .iter()
            .map(|(k, v)| format!("{k}:{v}"))
            .collect::<Vec<_>>()
            .join(", ");
        println!(
            "  {} {}",
            style("languages:").cyan().bold(),
            style(langs).dim()
        );
    }
    if !cat_counts.is_empty() {
        let cats = cat_counts
            .iter()
            .map(|(k, v)| format!("{k:?}:{v}"))
            .collect::<Vec<_>>()
            .join(", ");
        println!("  {} {}", style("habits:").cyan().bold(), style(cats).dim());
    }
    println!(
        "  {} {}",
        style("teacher:").cyan().bold(),
        style("coderabbit (tracking)").dim()
    );

    if findings.is_empty() {
        println!(
            "{}",
            style("No issues found — Ferret learned clean-review pattern.").dim()
        );
    } else {
        println!();
        println!(
            "{}",
            header.apply_to(format!("CodeRabbit findings ({})", findings.len()))
        );
        for f in &findings {
            let sev_style = match f.severity {
                Severity::Critical => Style::new().red().bold(),
                Severity::Major => Style::new().red().bold(),
                Severity::Minor => Style::new().yellow().bold(),
                Severity::Info => Style::new().dim(),
            };
            println!(
                "  {} [{}] {} — {}",
                style("▸").cyan(),
                sev_style.apply_to(format!("{:?}", f.severity)),
                style(f.hunk_id.as_deref().unwrap_or("-")).dim(),
                f.message
            );
            if let Some(s) = &f.suggestion {
                println!("      {} {}", style("↳").dim(), style(s).dim().italic());
            }
        }
    }

    // Show that Ferret is now remembering for next time
    let stats = store.corpus_stats().await?;
    println!();
    println!(
        "{}",
        style(format!(
            "Ferret corpus: {} snapshots, {} findings total",
            stats.snapshots, stats.findings
        ))
        .dim()
    );

    Ok(())
}

async fn run_dream(db: &str, target: &Path, limit: usize, legacy: bool) -> Result<()> {
    let canonical_target = target
        .canonicalize()
        .unwrap_or_else(|_| target.to_path_buf());
    if !canonical_target.exists() {
        anyhow::bail!("target does not exist: {}", canonical_target.display());
    }
    let target_dir = if canonical_target.is_file() {
        canonical_target
            .parent()
            .unwrap_or(Path::new("."))
            .to_path_buf()
    } else {
        canonical_target.clone()
    };

    let store = Store::open(db).await?;
    let findings = store
        .recent_findings(limit as i64)
        .await
        .unwrap_or_default();

    let spinner = spinner(&format!(
        "Converting {} recent findings to .dreams",
        findings.len()
    ));
    // Map severity -> priority, category -> workflow-friction
    let output = render_ferret_dreams(&target_dir, &findings).await;
    let dreams_dir = target_dir.join(".dreams");
    std::fs::create_dir_all(&dreams_dir)
        .with_context(|| format!("create {}", dreams_dir.display()))?;
    std::fs::create_dir_all(dreams_dir.join("history"))?;
    for lifecycle in ["completed.dreams", "rejected.dreams"] {
        let p = dreams_dir.join(lifecycle);
        if !p.exists() {
            // private: 0o600 on unix
            std::fs::write(&p, b"version: 1\ndreams: []\n")
                .with_context(|| format!("init {}", p.display()))?;
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt;
                std::fs::set_permissions(&p, std::fs::Permissions::from_mode(0o600))
                    .with_context(|| format!("protect {}", p.display()))?;
            }
        }
    }
    let active_path = dreams_dir.join("active.dreams");
    // atomic write via temp file + rename
    let tmp = dreams_dir.join(format!(".active.dreams.tmp.{}", std::process::id()));
    std::fs::write(&tmp, output.as_bytes()).with_context(|| format!("write {}", tmp.display()))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&tmp, std::fs::Permissions::from_mode(0o600))
            .with_context(|| format!("protect {}", tmp.display()))?;
    }
    std::fs::rename(&tmp, &active_path)
        .with_context(|| format!("rename to {}", active_path.display()))?;

    // history copy
    let date = Utc::now().format("%Y-%m-%d").to_string();
    let id = uuid::Uuid::new_v4()
        .to_string()
        .chars()
        .take(8)
        .collect::<String>();
    let hist_path = dreams_dir
        .join("history")
        .join(format!("{date}-{id}.dreams"));
    std::fs::write(&hist_path, output.as_bytes())?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&hist_path, std::fs::Permissions::from_mode(0o600))
            .with_context(|| format!("protect {}", hist_path.display()))?;
    }

    if legacy {
        let legacy_path = target_dir.join(".dream");
        std::fs::write(&legacy_path, output.as_bytes())?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(&legacy_path, std::fs::Permissions::from_mode(0o600))
                .with_context(|| format!("protect {}", legacy_path.display()))?;
        }
    }

    spinner.finish_with_message(style("Dream file written").green().to_string());

    println!(
        "{} {}",
        style("→ target:").cyan().bold(),
        style(target_dir.display()).bold()
    );
    println!(
        "  {} {}",
        style("findings:").cyan().bold(),
        style(findings.len()).bold()
    );
    println!(
        "  {} {}",
        style("file:").cyan().bold(),
        style(active_path.display()).dim()
    );
    if legacy {
        println!(
            "  {} {}",
            style("legacy:").cyan().bold(),
            style(target_dir.join(".dream").display()).dim()
        );
    }
    if findings.is_empty() {
        println!(
            "{}",
            style(
                "No recent findings — wrote empty dreams list. Run `ferret track` to learn first."
            )
            .dim()
        );
    } else {
        let header = Style::new().bold().underlined();
        println!("\n{}", header.apply_to("Dreams preview"));
        for (i, f) in findings.iter().take(5).enumerate() {
            println!(
                "  {} {} [{}] {}",
                style(format!("dream-{:03}", i + 1)).cyan(),
                style(format!("{:?}", f.severity)).dim(),
                style(format!("{:?}", f.category)).dim(),
                style(&f.message).bold()
            );
        }
        if findings.len() > 5 {
            println!(
                "  {}",
                style(format!("… and {} more", findings.len() - 5)).dim()
            );
        }
    }
    Ok(())
}

async fn render_ferret_dreams(target: &Path, findings: &[ferret_core::ReviewFinding]) -> String {
    use ferret_core::{Category, Severity};
    let project = target
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("workspace");
    let date = Utc::now().format("%Y-%m-%d").to_string();
    let avg_conf = 0.85; // ferret confidence is ranking signal
    let mut out = String::new();
    out.push_str("version: 1\n");
    out.push_str(&format!("project: {}\n", yaml_scalar(project)));
    out.push_str("generated:\n  by: ferret\n");
    out.push_str(&format!("  date: {date}\n  confidence: {avg_conf:.2}\n"));
    out.push_str("source:\n");
    out.push_str(&format!("  ferret_findings: {}\n", findings.len()));
    out.push_str(&format!("  snapshots: {}\n", 0)); // placeholder, not needed for spec
    out.push_str("  note: \"converted from ferret recent findings\"\n");
    out.push_str("\ndreams:\n");
    if findings.is_empty() {
        out.push_str("  []\n");
        return out;
    }
    for (idx, f) in findings.iter().enumerate() {
        let priority = match f.severity {
            Severity::Critical => "HIGH",
            Severity::Major => "HIGH",
            Severity::Minor => "MEDIUM",
            Severity::Info => "LOW",
        };
        let category = match f.category {
            Category::Safety => "safety-friction",
            Category::Architecture => "architecture-friction",
            Category::Performance => "performance-friction",
            Category::Testing => "testing-friction",
            Category::Style => "style-friction",
            Category::Documentation => "documentation-friction",
            Category::Other => "workflow-friction",
        };
        let title = truncate(&f.message, 120);
        let problem = &f.message;
        let reason = f
            .suggestion
            .as_deref()
            .unwrap_or("Recurring review friction detected by Ferret/CodeRabbit. Converted finding suggests a capability or guardrail to prevent recurrence.");
        let affected = if let Some(hunk) = &f.hunk_id {
            format!("      - {}\n", yaml_scalar(hunk))
        } else {
            "      - none identified\n".to_string()
        };
        let action = "create capability";
        out.push_str(&format!(
            "\n  - id: dream-{:03}\n    priority: {priority}\n    category: {category}\n    title: {}\n    problem: {}\n    evidence:\n      reason: {}\n      confidence: {:.2}\n      mutation_fitness: {:.2}\n    affected:\n{}    proposed_mutation:\n      action: {action}\n      capability: {}\n    acceptance:\n      - Evidence-backed intervention reduces recurrence of this friction\n      - Outcome is verified by tests or deterministic operational checks\n    expected_value: {}\n",
            idx + 1,
            yaml_scalar(&title),
            yaml_scalar(problem),
            yaml_scalar(reason),
            0.80,
            0.75,
            affected,
            yaml_scalar(&title),
            yaml_scalar("Reduces review churn; codifies team habit")
        ));
    }
    out
}

fn yaml_scalar(value: &str) -> String {
    let mut out = String::with_capacity(value.len() + 2);
    out.push('"');
    for ch in value.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn truncate(s: &str, max: usize) -> String {
    if s.len() <= max {
        s.to_string()
    } else {
        format!("{}…", &s[..max - 1])
    }
}

fn infer_slug(target: &Path) -> String {
    // Prefer git remote slug if available, else directory name
    if let Ok(repo) = git2::Repository::open(target) {
        if let Ok(remote) = repo.find_remote("origin") {
            if let Some(url) = remote.url() {
                // crude parse: github.com:org/repo or https://github.com/org/repo.git
                let cleaned = url
                    .trim_end_matches(".git")
                    .rsplit('/')
                    .take(2)
                    .collect::<Vec<_>>()
                    .into_iter()
                    .rev()
                    .collect::<Vec<_>>()
                    .join("/");
                if !cleaned.is_empty() && cleaned.contains('/') {
                    return cleaned;
                }
            }
        }
    }
    let name = target
        .file_name()
        .and_then(|s| s.to_str())
        .unwrap_or("local")
        .to_string();
    format!("local/{name}")
}

fn collect_hunks_for_track(target: &Path) -> Result<Vec<ferret_core::DiffHunk>> {
    // If target is a git repo and has diff, prefer git hunks for realism
    if target.is_dir() {
        std::fs::read_dir(target)
            .with_context(|| format!("read project directory {}", target.display()))?;
        // Try to collect files via recursive walk (skip hidden/large)
        let mut hunks = Vec::new();
        let mut stack = vec![target.to_path_buf()];
        let mut count = 0usize;
        while let Some(dir) = stack.pop() {
            if count > 300 {
                break;
            }
            let entries = match std::fs::read_dir(&dir) {
                Ok(e) => e,
                Err(_) => continue,
            };
            let mut entries = entries.flatten().collect::<Vec<_>>();
            entries.sort_by_key(|entry| entry.file_name());
            for entry in entries.into_iter().rev() {
                let path = entry.path();
                let fname = path.file_name().and_then(|s| s.to_str()).unwrap_or("");
                if fname.starts_with('.')
                    || fname == "target"
                    || fname == "node_modules"
                    || fname == ".git"
                {
                    continue;
                }
                if path.is_dir() {
                    stack.push(path);
                } else if path.is_file() {
                    // Filter by extension allowlist
                    let ext = path.extension().and_then(|s| s.to_str()).unwrap_or("");
                    let interesting = matches!(
                        ext,
                        "rs" | "py"
                            | "ts"
                            | "js"
                            | "tsx"
                            | "jsx"
                            | "go"
                            | "java"
                            | "rb"
                            | "php"
                            | "md"
                            | "toml"
                            | "yaml"
                            | "yml"
                            | "json"
                            | "sh"
                    );
                    if !interesting {
                        continue;
                    }
                    if let Ok(meta) = std::fs::metadata(&path) {
                        if meta.len() > 100_000 {
                            continue;
                        }
                    }
                    let content = std::fs::read_to_string(&path).unwrap_or_default();
                    if content.trim().is_empty() {
                        continue;
                    }
                    let rel = path
                        .strip_prefix(target)
                        .unwrap_or(&path)
                        .to_string_lossy()
                        .into_owned();
                    // Create a synthetic hunk: whole file as one hunk
                    let id = stable_hunk_id(&rel, &content);
                    let language = path.extension().map(|e| e.to_string_lossy().into_owned());
                    hunks.push(ferret_core::DiffHunk {
                        id,
                        file_path: rel,
                        old_start: 1,
                        old_lines: 0,
                        new_start: 1,
                        new_lines: content.lines().count() as u32,
                        content: content.chars().take(4000).collect(),
                        language,
                    });
                    count += 1;
                    if count >= 100 {
                        break;
                    }
                }
            }
        }
        hunks.sort_by(|left, right| left.file_path.cmp(&right.file_path));
        if !hunks.is_empty() {
            return Ok(hunks);
        }
    } else if target.is_file() {
        let content = std::fs::read_to_string(target)
            .with_context(|| format!("read project file {}", target.display()))?;
        let fname = target
            .file_name()
            .and_then(|s| s.to_str())
            .unwrap_or("file");
        let id = stable_hunk_id(fname, &content);
        return Ok(vec![ferret_core::DiffHunk {
            id,
            file_path: fname.to_string(),
            old_start: 1,
            old_lines: 0,
            new_start: 1,
            new_lines: content.lines().count() as u32,
            content: content.chars().take(4000).collect(),
            language: target.extension().map(|e| e.to_string_lossy().into_owned()),
        }]);
    }

    // Fallback: try git diff if we can find a repo
    if let Some(parent) = target.parent().filter(|p| p.exists()) {
        if let Ok(repo) = git2::Repository::open(parent) {
            if let Ok(head) = repo.head() {
                if let Some(oid) = head.target() {
                    // try HEAD vs HEAD~1
                    if let Ok(base) = repo.revparse_single(&format!("{oid}~1")) {
                        if let Ok(hunks) =
                            extract_hunks(parent, &base.id().to_string(), &oid.to_string())
                        {
                            if !hunks.is_empty() {
                                return Ok(hunks);
                            }
                        }
                    }
                }
            }
        }
    }
    Ok(Vec::new())
}

/// Remove `#[cfg(test)]`-gated items (typically `mod tests { ... }`) from Rust
/// source text before it's scanned for production-code smells. Panics and
/// `.unwrap()`/`.expect()` calls inside test code are idiomatic Rust, not a
/// safety issue in the shipped binary, so Rule 1 must not see them.
///
/// This is a textual, brace-depth-based strip rather than a full parse: it
/// looks for `#[cfg(test)]`, then removes everything from the next `{` to
/// its matching `}`. That covers the common `#[cfg(test)] mod tests { ... }`
/// and `#[cfg(test)] fn ... { ... }` shapes; it does not attempt to handle
/// `#[cfg(test)]` on brace-less items (e.g. a bare `use` statement).
fn strip_cfg_test_regions(content: &str) -> String {
    const MARKER: &str = "#[cfg(test)]";
    let mut out = String::with_capacity(content.len());
    let mut i = 0usize;
    while i < content.len() {
        if content[i..].starts_with(MARKER) {
            if let Some(rel_brace) = content[i..].find('{') {
                let brace_start = i + rel_brace;
                let bytes = content.as_bytes();
                let mut depth = 0i32;
                let mut j = brace_start;
                while j < content.len() {
                    match bytes[j] {
                        b'{' => depth += 1,
                        b'}' => {
                            depth -= 1;
                            if depth == 0 {
                                j += 1;
                                break;
                            }
                        }
                        _ => {}
                    }
                    j += 1;
                }
                i = j;
                continue;
            }
        }
        let ch = content[i..].chars().next().unwrap_or('\u{0}');
        out.push(ch);
        i += ch.len_utf8();
    }
    out
}

/// Whether `content` contains a `println!`/`console.log` call that is not
/// gated behind a condition mentioning `verbose`. CLI tools routinely print
/// user-facing status behind `if args.verbose { ... }` / `if verbose { ... }`;
/// that's intentional output, not a debug statement left over from
/// development, so Rule 3 must not flag it.
/// Whether `text` calls the real `println!` macro. A plain
/// `text.contains("println!")` also matches `eprintln!` — Ferret's own
/// recommended stderr-diagnostics channel, not a stray debug print — since
/// `"eprintln!"` contains `"println!"` as a substring. This checks that the
/// character immediately before the match isn't an identifier character, so
/// `eprintln!`/`sprintln!`-style macros don't count.
fn contains_bare_println(text: &str) -> bool {
    text.match_indices("println!").any(|(idx, _)| {
        !text[..idx]
            .chars()
            .next_back()
            .is_some_and(|c| c.is_alphanumeric() || c == '_')
    })
}

fn has_unguarded_debug_print(content: &str) -> bool {
    let mut guard_stack: Vec<bool> = Vec::new();
    let mut currently_guarded = false;
    for raw_line in content.lines() {
        let line = raw_line.trim();

        if (contains_bare_println(line) || line.contains("console.log")) && !currently_guarded {
            return true;
        }

        let opens_verbose_guard = line.to_ascii_lowercase().contains("verbose");
        for _ in 0..line.matches('{').count() {
            guard_stack.push(currently_guarded || opens_verbose_guard);
            currently_guarded = *guard_stack.last().unwrap();
        }
        for _ in 0..line.matches('}').count() {
            guard_stack.pop();
            currently_guarded = guard_stack.last().copied().unwrap_or(false);
        }
    }
    false
}

/// Whether `content` both (a) discards a fallible call's error via
/// `.unwrap_or(`, `.unwrap_or_default()`, or `.unwrap_or_else(`, and (b)
/// performs a destructive filesystem write (`fs::write`, `fs::copy`,
/// `.write_all(`, or a `truncate(true)` open). This is a coarse,
/// hunk-scoped co-occurrence check — like the other CodeRabbit-style rules
/// here, it does not trace whether the defaulted value is the one actually
/// written, trading precision for zero-setup detection.
fn has_error_swallow_before_write(content: &str) -> bool {
    let swallows_error = content.contains(".unwrap_or_default()")
        || content.contains(".unwrap_or(")
        || content.contains(".unwrap_or_else(");
    let writes_to_disk = content.contains("fs::write(")
        || content.contains("fs::copy(")
        || content.contains(".write_all(")
        || content.contains("truncate(true)");
    swallows_error && writes_to_disk
}

fn coderabbit_review(snapshot: &ReviewSnapshot) -> Vec<ferret_core::ReviewFinding> {
    use ferret_core::{Category, FindingId, ReviewFinding, Severity};
    let mut findings = Vec::new();
    for hunk in &snapshot.hunks {
        let content = &hunk.content;
        let file = &hunk.file_path;

        // Heuristic rules that mimic CodeRabbit style + Ferret tracking
        // Rule 1: panic/unwrap in Rust (excluding #[cfg(test)] code, see
        // strip_cfg_test_regions)
        let production_content = strip_cfg_test_regions(content);
        if production_content.contains("panic!")
            || production_content.contains(".unwrap()")
            || production_content.contains(".expect(")
        {
            findings.push(ReviewFinding {
                id: FindingId::new(),
                snapshot_id: snapshot.id,
                teacher: TeacherKind::CodeRabbit,
                hunk_id: Some(hunk.id.clone()),
                category: Category::Safety,
                severity: Severity::Major,
                message: format!("Avoid panic/unwrap in production paths ({file})"),
                suggestion: Some("Return Result instead".into()),
                rule_id: Some("safety/no-panic".into()),
                captured_at: Utc::now(),
            });
        }
        // Rule 2: TODO/FIXME
        if content.contains("TODO") || content.contains("FIXME") {
            findings.push(ReviewFinding {
                id: FindingId::new(),
                snapshot_id: snapshot.id,
                teacher: TeacherKind::CodeRabbit,
                hunk_id: Some(hunk.id.clone()),
                category: Category::Documentation,
                severity: Severity::Info,
                message: format!("TODO/FIXME left in {file} — track or resolve"),
                suggestion: None,
                rule_id: Some("docs/todo".into()),
                captured_at: Utc::now(),
            });
        }
        // Rule 3: console.log / println! debugging, excluding output gated
        // behind a `verbose` condition (see has_unguarded_debug_print)
        let looks_like_debug_print = (content.contains("console.log")
            || contains_bare_println(content))
            && file.ends_with(".rs")
            && content.lines().count() > 5;
        if looks_like_debug_print {
            // only flag if not in CLI main, and not verbose-gated output
            if !file.contains("main.rs") && has_unguarded_debug_print(content) {
                findings.push(ReviewFinding {
                    id: FindingId::new(),
                    snapshot_id: snapshot.id,
                    teacher: TeacherKind::CodeRabbit,
                    hunk_id: Some(hunk.id.clone()),
                    category: Category::Style,
                    severity: Severity::Minor,
                    message: format!("Debug print left in {file}"),
                    suggestion: Some("Remove or gate behind debug flag".into()),
                    rule_id: Some("style/no-debug-print".into()),
                    captured_at: Utc::now(),
                });
            }
        }
        // Rule 4: large file / long hunk
        if hunk.new_lines > 100 {
            findings.push(ReviewFinding {
                id: FindingId::new(),
                snapshot_id: snapshot.id,
                teacher: TeacherKind::CodeRabbit,
                hunk_id: Some(hunk.id.clone()),
                category: Category::Architecture,
                severity: Severity::Minor,
                message: format!(
                    "Large hunk ({} lines) in {file} — consider splitting",
                    hunk.new_lines
                ),
                suggestion: None,
                rule_id: Some("arch/large-hunk".into()),
                captured_at: Utc::now(),
            });
        }
        // Rule 5: missing error handling
        if file.ends_with(".rs")
            && content.contains("Result")
            && !content.contains("?")
            && content.contains("fn ")
        {
            findings.push(ReviewFinding {
                id: FindingId::new(),
                snapshot_id: snapshot.id,
                teacher: TeacherKind::CodeRabbit,
                hunk_id: Some(hunk.id.clone()),
                category: Category::Safety,
                severity: Severity::Minor,
                message: format!("Function returns Result but doesn't use `?` in {file}"),
                suggestion: Some("Propagate errors with `?`".into()),
                rule_id: Some("safety/error-propagation".into()),
                captured_at: Utc::now(),
            });
        }
        // Rule 6: error-swallowing feeding a destructive write. A fallible
        // read/parse whose error is discarded via unwrap_or/unwrap_or_default/
        // unwrap_or_else, then used as the payload of a filesystem write in
        // the same hunk, silently replaces the target's contents (often with
        // an empty string) instead of surfacing the failure. Surfaced by
        // scanning oip's src/main.rs: `clipboard.get_text().unwrap_or_default()`
        // feeds `fs::write(target, processed)`, wiping the target file to
        // empty whenever the clipboard read fails, with no warning.
        if file.ends_with(".rs") && has_error_swallow_before_write(&production_content) {
            findings.push(ReviewFinding {
                id: FindingId::new(),
                snapshot_id: snapshot.id,
                teacher: TeacherKind::CodeRabbit,
                hunk_id: Some(hunk.id.clone()),
                category: Category::Safety,
                severity: Severity::Major,
                message: format!(
                    "Error from a fallible call is swallowed via unwrap_or/unwrap_or_default/unwrap_or_else and then written to disk in {file} — a read failure will silently overwrite the target instead of aborting"
                ),
                suggestion: Some("Propagate the error (`?`) instead of defaulting before a destructive write".into()),
                rule_id: Some("safety/error-swallow-before-write".into()),
                captured_at: Utc::now(),
            });
        }
    }

    // Also run the stub teacher's ingest for completeness (currently empty)
    // and cap to 20 findings max (router limit)
    findings.truncate(20);
    findings
}

