fn print_predictions(predictions: &[PredictedFinding]) {
    if predictions.is_empty() {
        println!(
            "{}",
            style("No predictions. The corpus needs more findings.").dim()
        );
        return;
    }
    let header = Style::new().bold().underlined();
    println!(
        "{}",
        header.apply_to(format!("Predictions ({})", predictions.len()))
    );
    for p in predictions {
        let conf_style = confidence_style(p.confidence);
        println!(
            "  {} [{}] {} — {}",
            style("▸").cyan(),
            conf_style.apply_to(format!("{:.2}", p.confidence)),
            style(p.hunk_id.as_deref().unwrap_or("-")).dim(),
            p.message
        );
    }
}

fn print_routed(routed: &[ferret_route::RoutedFinding]) {
    if routed.is_empty() {
        println!("{}", style("Nothing to route.").dim());
        return;
    }
    let header = Style::new().bold().underlined();
    println!(
        "{}",
        header.apply_to(format!("Routing decisions ({})", routed.len()))
    );
    for r in routed {
        let (icon, route_style) = match r.route {
            Route::Solo => ("●", Style::new().green().bold()),
            Route::SoloWithOptionalVerify => ("◐", Style::new().yellow().bold()),
            Route::Escalate => ("○", Style::new().red().bold()),
        };
        let escalate = r
            .escalate_to
            .map(|t| format!(" → {}", t.as_str()))
            .unwrap_or_default();
        println!(
            "  {} {} {:.2} — {}{}",
            route_style.apply_to(icon),
            route_style.apply_to(format!("{:?}", r.route)),
            r.finding.confidence,
            r.finding.message,
            style(escalate).dim()
        );
    }
}

fn confidence_style(confidence: f32) -> Style {
    if confidence >= 0.98 {
        Style::new().green().bold()
    } else if confidence >= 0.75 {
        Style::new().yellow().bold()
    } else {
        Style::new().red().bold()
    }
}

fn load_hunks(
    repo_path: Option<&std::path::Path>,
    diff_path: Option<&std::path::Path>,
    base: &str,
    head: &str,
) -> Result<Vec<ferret_core::DiffHunk>> {
    if let Some(diff_path) = diff_path {
        let text = std::fs::read_to_string(diff_path)
            .with_context(|| format!("read diff {}", diff_path.display()))?;
        return Ok(hunks_from_unified_diff(&text));
    }
    if let Some(repo_path) = repo_path {
        return extract_hunks(repo_path, base, head);
    }
    anyhow::bail!("provide --path (git repo) or --diff (unified diff file)")
}

#[cfg(test)]
mod project_business_regression_tests {
    use super::*;

    struct TempTree(PathBuf);

    impl TempTree {
        fn new() -> Self {
            let path = std::env::temp_dir().join(format!(
                "ferret-project-regression-{}",
                uuid::Uuid::new_v4()
            ));
            std::fs::create_dir_all(&path).unwrap();
            Self(path)
        }
    }

    impl Drop for TempTree {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }

    #[test]
    fn direct_and_business_use_equivalent_project_analysis() {
        let tree = TempTree::new();
        let project_path = tree.0.join("app");
        std::fs::create_dir_all(project_path.join("src")).unwrap();
        std::fs::write(project_path.join("go.mod"), "module example/app\n").unwrap();
        std::fs::write(
            project_path.join("src/main.go"),
            "package main\nfunc main() {}\n",
        )
        .unwrap();

        let direct_project = business::project_at(&project_path, false).unwrap();
        let direct = scan_project(&direct_project).unwrap();
        let report = business::scan_business(
            &tree.0,
            &DiscoveryOptions {
                git: false,
                ..Default::default()
            },
            2,
            scan_project,
        )
        .unwrap();
        assert_eq!(report.projects.len(), 1);
        assert_eq!(report.projects[0].analysis.as_ref(), Some(&direct));
    }

    #[test]
    fn malformed_project_does_not_prevent_other_real_scans() {
        let tree = TempTree::new();
        let broken = tree.0.join("broken");
        let valid = tree.0.join("valid");
        std::fs::create_dir_all(&broken).unwrap();
        std::fs::create_dir_all(&valid).unwrap();
        std::fs::write(broken.join("package.json"), "{not-json").unwrap();
        std::fs::write(valid.join("go.mod"), "module valid\n").unwrap();

        let report = business::scan_business(
            &tree.0,
            &DiscoveryOptions {
                git: false,
                ..Default::default()
            },
            2,
            scan_project,
        )
        .unwrap();
        assert_eq!(report.summary.errors, 1);
        assert_eq!(report.summary.successful, 1);
        assert_eq!(report.summary.scanned, 2);
    }
}

#[cfg(test)]
mod coderabbit_rule_tests {
    use super::*;

    // Rule 1 (safety/no-panic) false positive: unwrap() that only appears
    // inside a #[cfg(test)] module is idiomatic Rust, not a production
    // panic risk. Surfaced by scanning bank's src/main.rs and src/creation.rs,
    // whose #[cfg(test)] mod tests blocks were flagged as "production" code.
    #[test]
    fn strip_cfg_test_regions_removes_test_only_unwrap() {
        let content = r#"
fn real_fn() -> anyhow::Result<()> {
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn t() {
        let x = Some(1).unwrap();
        assert_eq!(x, 1);
    }
}
"#;
        let stripped = strip_cfg_test_regions(content);
        assert!(!stripped.contains(".unwrap()"));
        assert!(stripped.contains("fn real_fn"));
    }

    #[test]
    fn strip_cfg_test_regions_keeps_production_unwrap() {
        let content = r#"
fn real_fn() {
    let x = Some(1).unwrap();
}
"#;
        let stripped = strip_cfg_test_regions(content);
        assert!(stripped.contains(".unwrap()"));
    }

    #[test]
    fn strip_cfg_test_regions_handles_multiple_test_blocks() {
        let content = r#"
#[cfg(test)]
mod tests_a {
    fn t() { let _ = Some(1).unwrap(); }
}

fn production() {}

#[cfg(test)]
mod tests_b {
    fn t() { let _ = Some(2).unwrap(); }
}
"#;
        let stripped = strip_cfg_test_regions(content);
        assert!(!stripped.contains(".unwrap()"));
        assert!(stripped.contains("fn production"));
    }

    // Rule 3 (style/no-debug-print) false positive: println! gated behind
    // `if args.verbose { ... }` is intentional CLI output, not a debug
    // statement left over from development. Surfaced by scanning bank's
    // src/creation.rs and src/permissions.rs verbose-mode output.
    #[test]
    fn verbose_gated_println_is_not_flagged() {
        let content = r#"
pub fn create_file(path: &Path, args: &Args) -> Result<()> {
    if path.exists() {
        if args.verbose {
            println!("File already exists: {}", colored_path(path, Color::Yellow));
        }
    } else {
        fs::File::create(path)?;
    }
    Ok(())
}
"#;
        assert!(!has_unguarded_debug_print(content));
    }

    #[test]
    fn unguarded_println_is_still_flagged() {
        let content = r#"
pub fn create_file(path: &Path) -> Result<()> {
    println!("debug: creating {:?}", path);
    fs::File::create(path)?;
    Ok(())
}
"#;
        assert!(has_unguarded_debug_print(content));
    }

    #[test]
    fn println_after_verbose_block_closes_is_still_flagged() {
        let content = r#"
pub fn f(args: &Args) {
    if args.verbose {
        println!("a");
    }
    println!("b");
}
"#;
        assert!(has_unguarded_debug_print(content));
    }

    // Regression: "eprintln!" contains "println!" as a substring
    // (eprintln! = "e" + "println!"), so a naive `.contains("println!")`
    // flagged every legitimate stderr-diagnostics call as a leftover debug
    // print. Observed against uni's src/run.rs, which is entirely eprintln!
    // telemetry and has no println! at all.
    #[test]
    fn eprintln_is_not_flagged_as_debug_print() {
        let content = r#"
pub fn f(e: &str) {
    eprintln!("uni: tool=amber stage=parse outcome=json_error error={e}");
    eprintln!("uni: internal error: a tool task panicked: {e}");
}
"#;
        assert!(!has_unguarded_debug_print(content));
        assert!(!contains_bare_println(content));
    }

    #[test]
    fn bare_println_is_still_detected_by_the_substring_guard() {
        assert!(contains_bare_println("println!(\"debug\");"));
        assert!(!contains_bare_println("eprintln!(\"telemetry\");"));
    }

    // Rule 6 (safety/error-swallow-before-write): a fallible read whose
    // error is discarded via unwrap_or_default(), then written straight to
    // disk, silently wipes the target on failure instead of erroring out.
    // Surfaced by scanning oip's src/main.rs.
    #[test]
    fn unwrap_or_default_feeding_fs_write_is_flagged() {
        let content = r#"
fn apply_clipboard_to_file(target: &PathBuf) {
    let mut clipboard = Clipboard::new().expect("Clipboard unavailable");
    let text = clipboard.get_text().unwrap_or_default();
    fs::write(target, text).expect("Write failed");
}
"#;
        assert!(has_error_swallow_before_write(content));
    }

    #[test]
    fn unwrap_or_else_feeding_write_all_is_flagged() {
        let content = r#"
fn save(mut f: File, data: Result<Vec<u8>, Error>) {
    let bytes = data.unwrap_or_else(|_| Vec::new());
    f.write_all(&bytes).expect("write failed");
}
"#;
        assert!(has_error_swallow_before_write(content));
    }

    #[test]
    fn unwrap_or_default_without_a_write_is_not_flagged() {
        let content = r#"
fn count(text: Option<&str>) -> usize {
    let s = text.unwrap_or_default();
    s.len()
}
"#;
        assert!(!has_error_swallow_before_write(content));
    }

    #[test]
    fn fs_write_without_error_swallowing_is_not_flagged() {
        let content = r#"
fn apply(target: &PathBuf, text: String) -> anyhow::Result<()> {
    fs::write(target, text)?;
    Ok(())
}
"#;
        assert!(!has_error_swallow_before_write(content));
    }
}

//! Minimal, thread-driven spinner/progress-bar replacement for the small
//! slice of `indicatif::ProgressBar` this crate used. `indicatif`'s own
//! terminal drawing is replaced with a local thread plus `\r` overwrite —
//! the same pattern already used for CLI spinners elsewhere in this
//! workspace (deckhand, deliver, bart) — with styling from `form3` instead
//! of `console`.

use form3::ansi::Color;
use form3::compat::Colorize;
use std::io::{self, Write};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Duration;

const TICK_CHARS: &[char] = &['⠁', '⠂', '⠄', '⡀', '⢀', '⠠', '⠐', '⠈'];
const BAR_WIDTH: usize = 40;

fn clear_line() {
    eprint!("\r\x1b[2K");
    let _ = io::stderr().flush();
}

/// An indefinite spinner, ticking on its own thread until finished.
pub struct Spinner {
    active: Arc<AtomicBool>,
    handle: Option<thread::JoinHandle<()>>,
}

pub fn spinner(msg: &str) -> Spinner {
    let msg = msg.to_string();
    let active = Arc::new(AtomicBool::new(true));
    let worker_active = Arc::clone(&active);
    let handle = thread::spawn(move || {
        let mut tick = 0usize;
        while worker_active.load(Ordering::Relaxed) {
            let glyph = TICK_CHARS[tick % TICK_CHARS.len()].to_string().color(Color::Cyan);
            eprint!("\r\x1b[2K{glyph} {msg}");
            let _ = io::stderr().flush();
            tick += 1;
            thread::sleep(Duration::from_millis(80));
        }
    });
    Spinner {
        active,
        handle: Some(handle),
    }
}

impl Spinner {
    fn stop(&mut self) {
        self.active.store(false, Ordering::Relaxed);
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
    }

    pub fn finish_with_message(mut self, message: impl AsRef<str>) {
        self.stop();
        let glyph = TICK_CHARS[0].to_string().color(Color::Cyan);
        eprintln!("\r\x1b[2K{glyph} {}", message.as_ref());
    }

    pub fn finish_and_clear(mut self) {
        self.stop();
        clear_line();
    }
}

/// A finished/simulated bar, kept only so callers can `finish_and_clear()` it.
pub struct HunkProgress;

impl HunkProgress {
    pub fn finish_and_clear(self) {
        clear_line();
    }
}

/// Plays a fixed-duration progress animation over `len` steps, then returns.
/// Mirrors the prior behaviour exactly: for `len == 0` this performs no
/// animation at all (no iterations, nothing drawn).
pub async fn hunk_progress(len: usize, msg: &str) -> HunkProgress {
    let denom = len.max(1);
    for step in 0..len {
        let glyph = TICK_CHARS[step % TICK_CHARS.len()].to_string().color(Color::Cyan);
        let filled = ((step + 1) as f64 / denom as f64 * BAR_WIDTH as f64).round() as usize;
        let filled = filled.min(BAR_WIDTH);
        let bar = format!(
            "{}{}",
            "#".repeat(filled).color(Color::Cyan),
            "-".repeat(BAR_WIDTH - filled).color(Color::Blue)
        );
        eprint!("\r\x1b[2K{glyph} {msg} [{bar}] {}/{len}", step + 1);
        let _ = io::stderr().flush();
        tokio::time::sleep(Duration::from_millis(25)).await;
    }
    HunkProgress
}

//! Drop-in shim for the small slice of `console::style`/`console::Style` this
//! crate used, backed by `form3::compat::Colorize` instead. Kept the same
//! call shape (`style(value).bold().cyan()`, `Style::new().bold()` +
//! `.apply_to(value)`) so call sites did not need to change, only the
//! `use console::{style, Style};` import line.

use form3::ansi::Color;
use form3::compat::Colorize;
use std::fmt;

#[derive(Debug, Clone, Copy, Default)]
struct Effects {
    fg: Option<Color>,
    bold: bool,
    dim: bool,
    italic: bool,
    underline: bool,
}

impl Effects {
    fn render(self, text: &str) -> String {
        let mut styled = text.normal();
        if let Some(color) = self.fg {
            styled = styled.color(color);
        }
        if self.bold {
            styled = styled.bold();
        }
        if self.dim {
            styled = styled.dimmed();
        }
        if self.italic {
            styled = styled.italic();
        }
        if self.underline {
            styled = styled.underline();
        }
        styled.to_string()
    }
}

macro_rules! effect_methods {
    ($self_ty:ty, $field:ident) => {
        pub fn bold(mut self) -> $self_ty {
            self.$field.bold = true;
            self
        }
        pub fn dim(mut self) -> $self_ty {
            self.$field.dim = true;
            self
        }
        pub fn italic(mut self) -> $self_ty {
            self.$field.italic = true;
            self
        }
        pub fn underlined(mut self) -> $self_ty {
            self.$field.underline = true;
            self
        }
        pub fn red(mut self) -> $self_ty {
            self.$field.fg = Some(Color::Red);
            self
        }
        pub fn green(mut self) -> $self_ty {
            self.$field.fg = Some(Color::Green);
            self
        }
        pub fn yellow(mut self) -> $self_ty {
            self.$field.fg = Some(Color::Yellow);
            self
        }
        pub fn cyan(mut self) -> $self_ty {
            self.$field.fg = Some(Color::Cyan);
            self
        }
    };
}

/// Mirrors `console::Style`: an effect bundle built once, applied to many values.
#[derive(Debug, Clone, Copy, Default)]
pub struct Style {
    effects: Effects,
}

impl Style {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn apply_to<T: fmt::Display>(&self, value: T) -> StyledValue<T> {
        StyledValue {
            value,
            effects: self.effects,
        }
    }

    effect_methods!(Self, effects);
}

/// Mirrors `console::style(value)`: a value paired with effects, rendered on `Display`.
pub struct StyledValue<T> {
    value: T,
    effects: Effects,
}

pub fn style<T: fmt::Display>(value: T) -> StyledValue<T> {
    StyledValue {
        value,
        effects: Effects::default(),
    }
}

impl<T: fmt::Display> StyledValue<T> {
    effect_methods!(Self, effects);
}

impl<T: fmt::Display> fmt::Display for StyledValue<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.effects.render(&self.value.to_string()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // `form3::term`'s colour override is process-global, so these tests must
    // not run concurrently with each other.
    static OVERRIDE_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

    #[test]
    fn style_fn_chains_color_and_attributes() {
        let _guard = OVERRIDE_LOCK.lock().unwrap();
        form3::term::set_override(true);
        let rendered = style("x").red().bold().to_string();
        form3::term::unset_override();
        assert!(rendered.contains('x'));
        assert!(rendered.contains("\x1b["));
    }

    #[test]
    fn style_struct_applies_to_multiple_values() {
        let _guard = OVERRIDE_LOCK.lock().unwrap();
        form3::term::set_override(true);
        let header = Style::new().bold().underlined();
        let styled = header.apply_to("a").to_string();
        let styled_again = header.apply_to("a").to_string();
        let plain = Style::new().apply_to("a").to_string();
        form3::term::unset_override();
        assert_eq!(styled_again, styled);
        assert_ne!(styled, plain);
    }
}

use std::fmt;

#[derive(Debug)]
pub enum FerretError {
    NotFound(String),
    InvalidInput(String),
    Storage(String),
}

impl fmt::Display for FerretError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::NotFound(s) => write!(f, "not found: {s}. Check the identifier and try again."),
            Self::InvalidInput(s) => write!(
                f,
                "invalid input: {s}. Provide a valid value and try again."
            ),
            Self::Storage(s) => write!(
                f,
                "storage error: {s}. Check the database path and try again."
            ),
        }
    }
}

