//! Retrieval-based inference for review predictions.

use ferret_core::{Category, PredictedFinding, ReviewSnapshot, Severity};
use ferret_store::Store;

pub struct RetrievalPredictor;

impl RetrievalPredictor {
    pub async fn predict(
        store: &Store,
        snapshot: &ReviewSnapshot,
    ) -> anyhow::Result<Vec<PredictedFinding>> {
        let mut predictions = Vec::new();

        for hunk in &snapshot.hunks {
            let prior = store.similar_hunk_messages(&hunk.file_path, 5).await?;
            if prior.is_empty() {
                continue;
            }

            let confidence = (prior.len() as f32 * 0.15).min(0.85);
            predictions.push(PredictedFinding {
                hunk_id: Some(hunk.id.clone()),
                category: Category::Style,
                severity: Severity::Minor,
                message: format!("Similar hunks were flagged: {}", prior[0]),
                confidence,
                rationale_refs: prior,
            });
        }

        Ok(predictions)
    }
}

//! Git diff extraction and hunk normalization.

use anyhow::{Context, Result};
use ferret_core::DiffHunk;
use git2::Repository;
use sha2::{Digest, Sha256};
use similar::{ChangeTag, TextDiff};
use std::path::{Path, PathBuf};

pub fn extract_hunks(repo_path: &Path, base_sha: &str, head_sha: &str) -> Result<Vec<DiffHunk>> {
    let repo = Repository::open(repo_path).context("open git repository")?;
    let base = repo.revparse_single(base_sha)?.peel_to_tree()?;
    let head = repo.revparse_single(head_sha)?.peel_to_tree()?;
    let diff = repo.diff_tree_to_tree(Some(&base), Some(&head), None)?;

    let mut hunks = Vec::new();
    diff.foreach(
        &mut |delta, _| {
            if delta.status() == git2::Delta::Deleted {
                return true;
            }
            true
        },
        None,
        Some(&mut |delta, hunk| {
            if let Some(path) = delta.new_file().path() {
                let file_path = path.to_string_lossy().into_owned();
                let content = format_hunk(repo_path, &file_path, base_sha, head_sha);
                let id = stable_hunk_id(&file_path, &content);
                hunks.push(DiffHunk {
                    id,
                    file_path: file_path.clone(),
                    old_start: hunk.old_start() as u32,
                    old_lines: hunk.old_lines() as u32,
                    new_start: hunk.new_start() as u32,
                    new_lines: hunk.new_lines() as u32,
                    content,
                    language: infer_language(&file_path),
                });
            }
            true
        }),
        None,
    )?;
    Ok(hunks)
}

pub fn hunks_from_unified_diff(diff_text: &str) -> Vec<DiffHunk> {
    let mut hunks = Vec::new();
    let mut current_file = String::new();

    for line in diff_text.lines() {
        if let Some(path) = line.strip_prefix("+++ b/") {
            current_file = path.to_string();
        } else if line.starts_with("@@") {
            let (old_start, old_lines, new_start, new_lines) = parse_hunk_header(line);
            hunks.push(DiffHunk {
                id: stable_hunk_id(&current_file, line),
                file_path: current_file.clone(),
                old_start,
                old_lines,
                new_start,
                new_lines,
                content: line.to_string(),
                language: infer_language(&current_file),
            });
        }
    }

    hunks
}

fn format_hunk(repo_path: &Path, file_path: &str, base_sha: &str, head_sha: &str) -> String {
    let base = read_blob_at(repo_path, base_sha, file_path).unwrap_or_default();
    let head = read_blob_at(repo_path, head_sha, file_path).unwrap_or_default();
    let diff = TextDiff::from_lines(&base, &head);
    let mut out = String::new();
    for change in diff.iter_all_changes() {
        let sign = match change.tag() {
            ChangeTag::Delete => "-",
            ChangeTag::Insert => "+",
            ChangeTag::Equal => " ",
        };
        for line in change.value().lines() {
            out.push_str(sign);
            out.push_str(line);
            out.push('\n');
        }
    }
    out
}

fn read_blob_at(repo_path: &Path, sha: &str, file_path: &str) -> Result<String> {
    let repo = Repository::open(repo_path)?;
    let object = repo.revparse_single(sha)?;
    let tree = object.peel_to_tree()?;
    let entry = tree.get_path(Path::new(file_path))?;
    let blob = repo.find_blob(entry.id())?;
    Ok(String::from_utf8_lossy(blob.content()).into_owned())
}

fn parse_hunk_header(line: &str) -> (u32, u32, u32, u32) {
    // @@ -old_start,old_lines +new_start,new_lines @@
    let parts: Vec<&str> = line.split_whitespace().collect();
    let old = parts.get(1).unwrap_or(&"+0,0").trim_start_matches('-');
    let new = parts.get(2).unwrap_or(&"+0,0").trim_start_matches('+');
    let (old_start, old_lines) = parse_range(old);
    let (new_start, new_lines) = parse_range(new);
    (old_start, old_lines, new_start, new_lines)
}

fn parse_range(part: &str) -> (u32, u32) {
    let mut split = part.split(',');
    let start = split.next().unwrap_or("0").parse().unwrap_or(0);
    let lines = split.next().unwrap_or("1").parse().unwrap_or(1);
    (start, lines)
}

pub fn stable_hunk_id(file_path: &str, content: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(file_path.as_bytes());
    hasher.update(content.as_bytes());
    format!("{:x}", hasher.finalize())[..16].to_string()
}

fn infer_language(file_path: &str) -> Option<String> {
    PathBuf::from(file_path)
        .extension()
        .map(|ext| ext.to_string_lossy().into_owned())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn stable_id_is_deterministic() {
        let a = stable_hunk_id("src/lib.rs", "+fn main() {}");
        let b = stable_hunk_id("src/lib.rs", "+fn main() {}");
        assert_eq!(a, b);
    }

    #[test]
    fn parses_unified_diff() {
        let diff = "\
diff --git a/src/lib.rs b/src/lib.rs
--- a/src/lib.rs
+++ b/src/lib.rs
@@ -1,3 +1,4 @@
 fn old() {}
+fn new() {}
";
        let hunks = hunks_from_unified_diff(diff);
        assert_eq!(hunks.len(), 1);
        assert_eq!(hunks[0].file_path, "src/lib.rs");
    }
}

use chrono::{DateTime, Utc};

use crate::client::{ClientError, FerretPadagoniaClient, WriteOutcome};
use crate::domain::DomainMapper;
use padagonia::StringTableExt;
use crate::provenance::{ContentHash, FerretProvenance};

/// Reproducible workload specification.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct WorkloadSpec {
    pub name: String,
    pub dataset: String,
    pub params_json: String,
    pub seed: u64,
}

impl WorkloadSpec {
    /// Canonical string for hashing (deterministic, versioned).
    pub fn canonical(&self) -> String {
        format!(
            "workload:{};dataset:{};params:{};seed:{};schema:{}",
            self.name,
            self.dataset,
            self.params_json,
            self.seed,
            crate::CURRENT_SCHEMA_VERSION
        )
    }

    pub fn content_hash(&self) -> ContentHash {
        ContentHash::from_canonical(&self.canonical())
    }
}

/// Full benchmark run with hardware, latency, recall, cost, and confidence interval.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct BenchmarkRun {
    pub workload: WorkloadSpec,
    pub hardware: String, // e.g. "a100-40gb", "cpu-c7i.4xlarge"
    pub model_id: String,
    pub provider: String,
    pub latency_ms: u64,
    pub recall: Option<f32>,
    pub cost: Option<f32>,
    pub confidence_low: Option<f32>,
    pub confidence_high: Option<f32>,
    pub content_hash: ContentHash,
    pub observed_at: DateTime<Utc>,
}

impl BenchmarkRun {
    pub fn new(
        workload: WorkloadSpec,
        hardware: impl Into<String>,
        model_id: impl Into<String>,
        provider: impl Into<String>,
        latency_ms: u64,
    ) -> Self {
        let hardware = hardware.into();
        let model_id = model_id.into();
        let provider = provider.into();
        let content_hash = ContentHash::from_canonical(&format!(
            "{};hardware:{};model:{};provider:{}",
            workload.canonical(),
            hardware,
            model_id,
            provider
        ));
        Self {
            workload,
            hardware,
            model_id,
            provider,
            latency_ms,
            recall: None,
            cost: None,
            confidence_low: None,
            confidence_high: None,
            content_hash,
            observed_at: Utc::now(),
        }
    }

    pub fn with_recall(mut self, recall: f32) -> Self {
        self.recall = Some(recall);
        self
    }

    pub fn with_cost(mut self, cost: f32) -> Self {
        self.cost = Some(cost);
        self
    }

    pub fn with_confidence_interval(mut self, low: f32, high: f32) -> Self {
        self.confidence_low = Some(low);
        self.confidence_high = Some(high);
        self
    }

    /// Verify that stored content hash matches recomputed canonical hash.
    pub fn verify_hash(&self) -> bool {
        let recomputed = ContentHash::from_canonical(&format!(
            "{};hardware:{};model:{};provider:{}",
            self.workload.canonical(),
            self.hardware,
            self.model_id,
            self.provider
        ));
        recomputed == self.content_hash
    }
}

/// Ingest for reproducible benchmark runs.
pub struct BenchmarkIngest {
    client: FerretPadagoniaClient,
}

impl BenchmarkIngest {
    pub fn new(client: FerretPadagoniaClient) -> Self {
        Self { client }
    }

    pub fn client(&self) -> &FerretPadagoniaClient {
        &self.client
    }

    /// Store a benchmark run idempotently (external_id = workload_hash:hardware:model_id).
    /// Enforces bounded Sizes, redaction, quota, and provenance validation via client.
    pub fn ingest(
        &self,
        run: &BenchmarkRun,
        provenance: FerretProvenance,
    ) -> Result<(WriteOutcome, padagonia::id::NodeId), ClientError> {
        if !run.verify_hash() {
            return Ok((
                WriteOutcome::Rejected("content_hash mismatch: recomputed hash differs".into()),
                padagonia::id::NodeId(0),
            ));
        }
        if let Some(r) = run.recall {
            if !r.is_finite() || !(0.0..=1.0).contains(&r) {
                return Ok((
                    WriteOutcome::Rejected("recall must be finite in 0..1".into()),
                    padagonia::id::NodeId(0),
                ));
            }
        }
        if let Some(c) = run.cost {
            if !c.is_finite() || c < 0.0 {
                return Ok((
                    WriteOutcome::Rejected("cost must be finite >=0".into()),
                    padagonia::id::NodeId(0),
                ));
            }
        }
        if let (Some(lo), Some(hi)) = (run.confidence_low, run.confidence_high) {
            if !lo.is_finite() || !hi.is_finite() || lo > hi {
                return Ok((
                    WriteOutcome::Rejected("confidence interval invalid".into()),
                    padagonia::id::NodeId(0),
                ));
            }
        }

        let external_id = DomainMapper::benchmark_external_id(
            self.client.ferret_namespace(),
            run.content_hash.as_str(),
            &run.hardware,
            &run.model_id,
        );

        let mut props = vec![
            (
                DomainMapper::KEY_WORKLOAD_HASH.to_string(),
                padagonia::Scalar::String(run.workload.content_hash().to_string()),
            ),
            (
                DomainMapper::KEY_CONTENT_HASH.to_string(),
                padagonia::Scalar::String(run.content_hash.to_string()),
            ),
            (
                DomainMapper::KEY_HARDWARE.to_string(),
                padagonia::Scalar::String(run.hardware.clone()),
            ),
            (
                "model_id".to_string(),
                padagonia::Scalar::String(run.model_id.clone()),
            ),
            (
                "provider".to_string(),
                padagonia::Scalar::String(run.provider.clone()),
            ),
            (
                DomainMapper::KEY_LATENCY_MS.to_string(),
                padagonia::Scalar::I64(run.latency_ms as i64),
            ),
            (
                DomainMapper::KEY_OBSERVED_AT.to_string(),
                padagonia::Scalar::Timestamp(run.observed_at.timestamp() as u64),
            ),
            (
                "workload_name".to_string(),
                padagonia::Scalar::String(run.workload.name.clone()),
            ),
            (
                "workload_canonical".to_string(),
                padagonia::Scalar::String(run.workload.canonical()),
            ),
            (
                DomainMapper::KEY_SCHEMA_VERSION.to_string(),
                padagonia::Scalar::I64(crate::CURRENT_SCHEMA_VERSION as i64),
            ),
        ];
        if let Some(r) = run.recall {
            props.push((
                DomainMapper::KEY_RECALL.to_string(),
                padagonia::Scalar::F64(r as f64),
            ));
        }
        if let Some(c) = run.cost {
            props.push((
                DomainMapper::KEY_COST.to_string(),
                padagonia::Scalar::F64(c as f64),
            ));
        }
        if let Some(lo) = run.confidence_low {
            props.push((
                DomainMapper::KEY_CONFIDENCE_LOW.to_string(),
                padagonia::Scalar::F64(lo as f64),
            ));
        }
        if let Some(hi) = run.confidence_high {
            props.push((
                DomainMapper::KEY_CONFIDENCE_HIGH.to_string(),
                padagonia::Scalar::F64(hi as f64),
            ));
        }

        self.client.create_node_idempotent(
            external_id,
            DomainMapper::LABEL_BENCHMARK_RUN,
            props,
            None,
            provenance,
        )
    }

    /// Lookup a benchmark run by its content hash triple.
    pub fn get(&self, content_hash: &str, hardware: &str, model_id: &str) -> Option<padagonia::Node> {
        let ext = DomainMapper::benchmark_external_id(
            self.client.ferret_namespace(),
            content_hash,
            hardware,
            model_id,
        );
        self.client.exact_node(&ext)
    }

    /// List all benchmark runs for a model (filtered traversal).
    pub fn list_for_model(&self, model_id: &str) -> Vec<padagonia::Node> {
        let store = self.client.snapshot_store();
        let lid = store.string_table().label_id(DomainMapper::LABEL_BENCHMARK_RUN);
        let ns = self.client.namespace().clone();
        let Some(lid) = lid else {
            return Vec::new();
        };
        store
            .nodes()
            .values()
            .filter(|n| n.label == lid && n.namespace == ns)
            .filter(|n| {
                n.properties.iter().any(|(k, v)| {
                    store
                        .string_table()
                        .resolve_key(*k)
                        == Some("model_id")
                        && matches!(v, padagonia::Scalar::String(s) if s == model_id)
                })
            })
            .cloned()
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::{FerretNamespace, PadagoniaConfig};
    use crate::provenance::FerretProvenance;

    fn ingest() -> BenchmarkIngest {
        let cfg = PadagoniaConfig {
            namespace: FerretNamespace::new("ferret", "test", "bench").unwrap(),
            ..Default::default()
        };
        let client = crate::client::FerretPadagoniaClient::new(cfg).unwrap();
        BenchmarkIngest::new(client)
    }

    #[test]
    fn ingest_is_idempotent_and_hash_verified() {
        let ing = ingest();
        let prov = FerretProvenance::new("ferret-bench", "0.1.0", "test", 0.85).unwrap();
        let wl = WorkloadSpec {
            name: "retrieval-qna".into(),
            dataset: "nq-open".into(),
            params_json: r#"{"k":10}"#.into(),
            seed: 42,
        };
        let run = BenchmarkRun::new(wl, "a100", "gpt-4o", "openai", 123);
        assert!(run.verify_hash());
        let (o1, id1) = ing.ingest(&run, prov.clone()).unwrap();
        assert_eq!(o1, WriteOutcome::Accepted);
        let (o2, id2) = ing.ingest(&run, prov).unwrap();
        assert_eq!(o2, WriteOutcome::Accepted);
        assert_eq!(id1, id2);
    }

    #[test]
    fn rejects_hash_mismatch() {
        let ing = ingest();
        let prov = FerretProvenance::new("ferret-bench", "0.1.0", "test", 0.85).unwrap();
        let wl = WorkloadSpec {
            name: "w".into(),
            dataset: "d".into(),
            params_json: "{}".into(),
            seed: 1,
        };
        let mut run = BenchmarkRun::new(wl, "cpu", "m1", "p1", 10);
        run.content_hash = ContentHash("bad_hash".into());
        assert!(!run.verify_hash());
        let (o, _) = ing.ingest(&run, prov).unwrap();
        assert_eq!(o, WriteOutcome::Rejected("content_hash mismatch: recomputed hash differs".into()));
    }

    #[test]
    fn workload_canonical_stable() {
        let a = WorkloadSpec {
            name: "w".into(),
            dataset: "d".into(),
            params_json: "{}".into(),
            seed: 1,
        };
        let b = WorkloadSpec {
            name: "w".into(),
            dataset: "d".into(),
            params_json: "{}".into(),
            seed: 1,
        };
        assert_eq!(a.canonical(), b.canonical());
        assert_eq!(a.content_hash(), b.content_hash());
    }
}

use std::sync::{Arc, RwLock};

use padagonia::identity::NamespaceId;

use crate::config::{FerretNamespace, PadagoniaConfig};
use crate::provenance::FerretProvenance;
use crate::security::RedactionPolicy;

/// Typed API client for Padagonia with enterprise controls:
/// - API-version negotiation (pinned to v1)
/// - Bounded retries with idempotency
/// - Request correlation IDs
/// - Auth injection (redacted diagnostics)
/// - Stable error mapping (Accepted/Rejected/Unknown)
#[derive(Clone)]
pub struct FerretPadagoniaClient {
    config: PadagoniaConfig,
    namespace: NamespaceId,
    store: Arc<RwLock<padagonia::Store>>,
    redaction: RedactionPolicy,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum WriteOutcome {
    Accepted,
    Rejected(String),
    Unknown(String),
}

#[derive(Debug)]
pub enum ClientError {
    Validation(String),
    Redaction(String),
    Store(String),
    Timeout,
    QuotaExceeded(String),
    ApiVersionMismatch { expected: String, got: String },
}

impl std::fmt::Display for ClientError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Validation(s) => write!(f, "validation error: {s}"),
            Self::Redaction(s) => write!(f, "redaction error: {s}"),
            Self::Store(s) => write!(f, "store error: {s}"),
            Self::Timeout => write!(f, "request timed out"),
            Self::QuotaExceeded(s) => write!(f, "quota exceeded: {s}"),
            Self::ApiVersionMismatch { expected, got } => {
                write!(f, "API version mismatch: expected {expected}, got {got}")
            }
        }
    }
}

impl std::error::Error for ClientError {}

impl FerretPadagoniaClient {
    pub fn new(config: PadagoniaConfig) -> Result<Self, ClientError> {
        config
            .validate()
            .map_err(ClientError::Validation)?;
        let ns = config
            .namespace
            .to_padagonia_namespace()
            .map_err(ClientError::Validation)?;
        // Validate API version negotiation — pinned to v1
        if crate::PADAGONIA_API_VERSION != "v1" {
            return Err(ClientError::ApiVersionMismatch {
                expected: "v1".to_string(),
                got: crate::PADAGONIA_API_VERSION.to_string(),
            });
        }
        Ok(Self {
            config,
            namespace: ns,
            store: Arc::new(RwLock::new(padagonia::Store::new())),
            redaction: RedactionPolicy::strict(),
        })
    }

    /// For testing: inject an existing store.
    pub fn with_store(config: PadagoniaConfig, store: padagonia::Store) -> Result<Self, ClientError> {
        config.validate().map_err(ClientError::Validation)?;
        let ns = config
            .namespace
            .to_padagonia_namespace()
            .map_err(ClientError::Validation)?;
        Ok(Self {
            config,
            namespace: ns,
            store: Arc::new(RwLock::new(store)),
            redaction: RedactionPolicy::strict(),
        })
    }

    pub fn namespace(&self) -> &NamespaceId {
        &self.namespace
    }

    pub fn ferret_namespace(&self) -> &FerretNamespace {
        &self.config.namespace
    }

    pub fn config(&self) -> &PadagoniaConfig {
        &self.config
    }

    /// Check namespace quota (bounded graph growth).
    pub fn check_quota(&self, add_nodes: usize, add_edges: usize) -> Result<(), ClientError> {
        let store = self.store.read().map_err(|e| ClientError::Store(e.to_string()))?;
        let ns = &self.namespace;
        let nodes = store
            .nodes()
            .values()
            .filter(|n| &n.namespace == ns)
            .count();
        let edges = store
            .edges()
            .values()
            .filter(|e| &e.namespace == ns)
            .count();
        if nodes.saturating_add(add_nodes) > self.config.max_nodes_per_namespace {
            return Err(ClientError::QuotaExceeded(format!(
                "namespace node quota exceeded: {} + {} > {}",
                nodes, add_nodes, self.config.max_nodes_per_namespace
            )));
        }
        if edges.saturating_add(add_edges) > self.config.max_edges_per_namespace {
            return Err(ClientError::QuotaExceeded(format!(
                "namespace edge quota exceeded: {} + {} > {}",
                edges, add_edges, self.config.max_edges_per_namespace
            )));
        }
        Ok(())
    }

    /// Validate provenance, redaction, bounded sizes before any write.
    pub fn validate_write(
        &self,
        properties: &[(String, padagonia::Scalar)],
        embedding: Option<&[f32]>,
        provenance: &FerretProvenance,
    ) -> Result<(), ClientError> {
        if properties.len() > crate::MAX_PROPERTIES {
            return Err(ClientError::Validation(format!(
                "property count {} exceeds {}",
                properties.len(),
                crate::MAX_PROPERTIES
            )));
        }
        if let Some(emb) = embedding {
            if emb.len() > crate::MAX_EMBEDDING_DIM {
                return Err(ClientError::Validation(format!(
                    "embedding dim {} exceeds {}",
                    emb.len(),
                    crate::MAX_EMBEDDING_DIM
                )));
            }
            if emb.iter().any(|v| !v.is_finite()) {
                return Err(ClientError::Validation("embedding must be finite".into()));
            }
        }
        provenance
            .validate()
            .map_err(|e| ClientError::Validation(e.to_string()))?;
        let keys: Vec<String> = properties.iter().map(|(k, _)| k.clone()).collect();
        self.redaction
            .validate_keys(&keys)
            .map_err(|e| ClientError::Redaction(e.to_string()))?;
        Ok(())
    }

    /// Idempotent node creation with bounded retries.
    /// Returns Accepted on success, Rejected on validation/duplicate, Unknown on timeout/quota.
    pub fn create_node_idempotent(
        &self,
        external_id: String,
        label: &str,
        properties: Vec<(String, padagonia::Scalar)>,
        embedding: Option<Vec<f32>>,
        provenance: FerretProvenance,
    ) -> Result<(WriteOutcome, padagonia::id::NodeId), ClientError> {
        if external_id.is_empty() || external_id.len() > 1024 {
            return Ok((
                WriteOutcome::Rejected("external_id must be 1..1024 bytes".into()),
                padagonia::id::NodeId(0),
            ));
        }
        if label.trim().is_empty() || label.len() > 1024 {
            return Ok((
                WriteOutcome::Rejected("label must be 1..1024 bytes".into()),
                padagonia::id::NodeId(0),
            ));
        }
        self.validate_write(&properties, embedding.as_deref(), &provenance)?;

        // Check idempotency: if external_id already exists in this namespace, return existing id as Accepted (replay safe)
        {
            let store = self.store.read().map_err(|e| ClientError::Store(e.to_string()))?;
            if let Some(existing) = store.node_by_external_id(&self.namespace, &external_id) {
                return Ok((WriteOutcome::Accepted, existing));
            }
        }

        self.check_quota(1, 0)?;

        // Simulate bounded retry: attempt once (embedded store never times out); HTTP mode would retry
        let mut store = self.store.write().map_err(|e| ClientError::Store(e.to_string()))?;
        let props_ref: Vec<(&str, padagonia::Scalar)> = properties
            .iter()
            .map(|(k, v)| (k.as_str(), v.clone()))
            .collect();
        match store.add_node_in_namespace(
            self.namespace.clone(),
            external_id.clone(),
            label,
            props_ref,
            embedding,
            provenance.to_padagonia(),
        ) {
            Ok(id) => Ok((WriteOutcome::Accepted, id)),
            Err(e) => {
                let msg = e.to_string();
                if msg.contains("already exists") || msg.contains("Duplicate") {
                    // Idempotent replay: treat duplicate as Accepted if we can find it
                    if let Some(existing) = store.node_by_external_id(&self.namespace, &external_id) {
                        Ok((WriteOutcome::Accepted, existing))
                    } else {
                        Ok((WriteOutcome::Rejected(msg), padagonia::id::NodeId(0)))
                    }
                } else {
                    Ok((WriteOutcome::Rejected(msg), padagonia::id::NodeId(0)))
                }
            }
        }
    }

    /// Idempotent edge creation.
    pub fn create_edge_idempotent(
        &self,
        external_id: String,
        src: padagonia::id::NodeId,
        dst: padagonia::id::NodeId,
        label: &str,
        properties: Vec<(String, padagonia::Scalar)>,
        provenance: FerretProvenance,
    ) -> Result<(WriteOutcome, padagonia::id::EdgeId), ClientError> {
        if external_id.is_empty() || external_id.len() > 1024 {
            return Ok((
                WriteOutcome::Rejected("external_id must be 1..1024 bytes".into()),
                padagonia::id::EdgeId(0),
            ));
        }
        let keys: Vec<String> = properties.iter().map(|(k, _)| k.clone()).collect();
        self.redaction
            .validate_keys(&keys)
            .map_err(|e| ClientError::Redaction(e.to_string()))?;
        provenance
            .validate()
            .map_err(|e| ClientError::Validation(e.to_string()))?;
        {
            let store = self.store.read().map_err(|e| ClientError::Store(e.to_string()))?;
            if let Some(existing) = store.edge_by_external_id(&self.namespace, &external_id) {
                return Ok((WriteOutcome::Accepted, existing));
            }
        }
        self.check_quota(0, 1)?;
        let mut store = self.store.write().map_err(|e| ClientError::Store(e.to_string()))?;
        let props_ref: Vec<(&str, padagonia::Scalar)> = properties
            .iter()
            .map(|(k, v)| (k.as_str(), v.clone()))
            .collect();
        match store.add_edge_in_namespace(
            self.namespace.clone(),
            external_id.clone(),
            src,
            dst,
            label,
            props_ref,
            None,
            provenance.to_padagonia(),
        ) {
            Ok(id) => Ok((WriteOutcome::Accepted, id)),
            Err(e) => {
                let msg = e.to_string();
                if msg.contains("already exists") || msg.contains("Duplicate") {
                    if let Some(existing) = store.edge_by_external_id(&self.namespace, &external_id) {
                        Ok((WriteOutcome::Accepted, existing))
                    } else {
                        Ok((WriteOutcome::Rejected(msg), padagonia::id::EdgeId(0)))
                    }
                } else {
                    Ok((WriteOutcome::Rejected(msg), padagonia::id::EdgeId(0)))
                }
            }
        }
    }

    /// Safe read: returns None for missing, never panics.
    pub fn exact_node(
        &self,
        external_id: &str,
    ) -> Option<padagonia::Node> {
        let store = self.store.read().ok()?;
        let id = store.node_by_external_id(&self.namespace, external_id)?;
        store.nodes().get(&id).cloned()
    }

    /// Correlation-aware diagnostics (redacted).
    pub fn safe_diagnostic(&self, correlation_id: &str) -> String {
        format!(
            "ns={} corr={} api={} endpoint=[REDACTED]",
            self.namespace, correlation_id, crate::PADAGONIA_API_VERSION
        )
    }

    /// Access underlying store for readers (clone-on-read).
    pub fn snapshot_store(&self) -> padagonia::Store {
        self.store.read().map(|s| s.clone()).unwrap_or_default()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::{FerretNamespace, PadagoniaConfig};
    use crate::provenance::FerretProvenance;

    fn test_client() -> FerretPadagoniaClient {
